-- Generated by tools/build-live-migration.py from the inspected QA source.
-- Additive Live installation on production; forward-compatible with existing QA.
-- All broadcasting, recording, delivery and reminder gates retain their values.
begin;
set local lock_timeout='3s';
set local statement_timeout='60s';
do $install$ begin
 if to_regnamespace('live_streams') is null then
  execute $live_core$
-- Live discovery and control plane. Audience media stays on the CDN.
-- This migration does not enable broadcasting, payments, or claim a capacity.
set local lock_timeout='3s';
set local statement_timeout='60s';
create schema live_streams;
revoke all on schema live_streams from public,anon,authenticated;
grant usage on schema live_streams to authenticated,service_role;

create table live_streams.settings (
 singleton boolean primary key default true check(singleton),
 create_enabled boolean not null default true, stage_enabled boolean not null default false,
 delivery_enabled boolean not null default false, private_delivery_enabled boolean not null default false,
 chat_enabled boolean not null default true, recording_enabled boolean not null default false,
 reminders_enabled boolean not null default false, gifts_enabled boolean not null default false,
 max_stage_members integer not null default 12 check(max_stage_members between 2 and 20),
 max_active_broadcasts integer not null default 10 check(max_active_broadcasts between 1 and 100000),
 max_chat_messages_per_second integer not null default 20 check(max_chat_messages_per_second between 1 and 100),
 capacity_evidence_ref text, updated_at timestamptz not null default now()
);
insert into live_streams.settings(singleton) values(true);
create table live_streams.sessions (
 id uuid primary key default gen_random_uuid(), host_id uuid not null references public.profiles(id) on delete cascade,
 title text not null check(length(title) between 1 and 120), description text not null default '' check(length(description)<=2000),
 topic text not null check(topic in ('irl','gaming','news','politics','business','music','concerts','education','sports','events','other')),
 audience text not null default 'public' check(audience in ('public','followers','invite')),
 state text not null default 'draft' check(state in ('draft','scheduled','backstage','starting','live','reconnecting','ending','ended','cancelled')),
 scheduled_at timestamptz, started_at timestamptz, ended_at timestamptz, thumbnail_url text,cover_object_path text,
 viewer_count bigint check(viewer_count>=0), viewer_count_at timestamptz,
 chat_mode text not null default 'open' check(chat_mode in ('open','followers','closed')),
 slow_mode_seconds integer not null default 0 check(slow_mode_seconds between 0 and 120),
 recording_enabled boolean not null default false, replay_available boolean not null default false,
 language text not null default 'en' check(length(language) between 2 and 20),
 pinned_message_id uuid, chat_epoch uuid not null default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check(thumbnail_url is null or (length(thumbnail_url)<=2048 and thumbnail_url like 'https://%'))
);
create index live_sessions_directory on live_streams.sessions(state,created_at desc,id desc);
create index live_sessions_topic on live_streams.sessions(topic,state,created_at desc,id desc);
create index live_sessions_host on live_streams.sessions(host_id,created_at desc,id desc);
create index live_sessions_upcoming on live_streams.sessions(scheduled_at,id) where state='scheduled';
create table live_streams.members (
 session_id uuid not null references live_streams.sessions(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade,
 role text not null check(role in ('producer','camera','guest','moderator','viewer')),
 status text not null default 'invited' check(status in ('invited','accepted','removed')),
 provider_identity uuid not null default gen_random_uuid(), created_at timestamptz not null default now(),
 primary key(session_id,user_id)
);
create index live_members_user on live_streams.members(user_id,session_id) where status<>'removed';
create table live_streams.exclusions (
 session_id uuid not null references live_streams.sessions(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade, actor_id uuid not null,
 reason text not null check(length(reason) between 1 and 1000), created_at timestamptz not null default now(),
 primary key(session_id,user_id)
);
create table live_streams.messages (
 id uuid primary key, session_id uuid not null references live_streams.sessions(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade, body text not null check(length(body) between 1 and 500),
 removed boolean not null default false, created_at timestamptz not null default now()
);
create index live_messages_history on live_streams.messages(session_id,created_at desc,id desc);
create index live_messages_user on live_streams.messages(user_id,created_at desc);
create index live_messages_retention on live_streams.messages(created_at,id);
create table live_streams.commands (
 actor_id uuid not null references auth.users(id) on delete cascade, request_id uuid not null,
 session_id uuid references live_streams.sessions(id) on delete cascade, action text not null, payload jsonb not null,
 result jsonb, created_at timestamptz not null default now(), primary key(actor_id,request_id)
);
create index live_commands_retention on live_streams.commands(created_at,actor_id,request_id);
create table live_streams.rate_limits (
 scope text not null, key text not null, window_start timestamptz not null, count integer not null,
 primary key(scope,key,window_start)
);
create index live_rate_retention on live_streams.rate_limits(window_start);
create table live_streams.reports (
 id uuid primary key default gen_random_uuid(), session_id uuid not null references live_streams.sessions(id) on delete cascade,
 reporter_id uuid not null references public.profiles(id) on delete cascade, message_id uuid,
 reason text not null check(length(reason) between 1 and 2000), state text not null default 'open' check(state in ('open','resolved')),
 resolved_by uuid, resolution text, created_at timestamptz not null default now()
);
create index live_reports_session on live_streams.reports(session_id,created_at desc,id desc);
create index live_reports_open on live_streams.reports(created_at desc,id desc) where state='open';
create index live_reports_reporter on live_streams.reports(reporter_id,created_at desc);
create table live_streams.audit (
 id uuid primary key default gen_random_uuid(), session_id uuid not null references live_streams.sessions(id) on delete cascade,
 actor_id uuid not null, action text not null, reason text, payload jsonb not null default '{}', created_at timestamptz not null default now()
);
create index live_audit_session on live_streams.audit(session_id,created_at desc,id desc);
create table live_streams.reminders (
 session_id uuid not null references live_streams.sessions(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(),
 primary key(session_id,user_id)
);
create index live_reminders_user on live_streams.reminders(user_id,session_id);
create table live_streams.provider_sessions (
 session_id uuid primary key references live_streams.sessions(id) on delete cascade,
 room_name text not null unique, instance_id uuid not null unique default gen_random_uuid(),
 playback_path text, replay_path text, active_scene jsonb not null default '{"preset":"host"}',
 published_participants jsonb not null default '[]', last_event_at timestamptz, last_event_sequence bigint not null default 0,
 error text, created_at timestamptz not null default now()
);
alter table live_streams.provider_sessions add column authority_actor_id uuid,add column authority_session_id uuid,add column authority_checked_at timestamptz;
create table live_streams.stage_grants (
 id uuid primary key default gen_random_uuid(), session_id uuid not null references live_streams.sessions(id) on delete cascade,
 user_id uuid not null, auth_session_id uuid not null, provider_identity uuid not null,
 expires_at timestamptz not null, revoked_at timestamptz, checked_at timestamptz, created_at timestamptz not null default now(),
 unique(session_id,user_id,auth_session_id,provider_identity)
);
create index live_stage_grants_active on live_streams.stage_grants(session_id,user_id) where revoked_at is null;
create index live_stage_grants_check on live_streams.stage_grants(checked_at nulls first,id) where revoked_at is null;
create index live_stage_grants_retention on live_streams.stage_grants(created_at,id);
create table live_streams.provider_events (
 event_id text primary key check(length(event_id) between 1 and 200), session_id uuid not null references live_streams.sessions(id) on delete cascade,
 event_type text not null, event_time timestamptz not null, digest text not null, created_at timestamptz not null default now()
);
create index live_provider_events_retention on live_streams.provider_events(created_at,event_id);
create table live_streams.controls (
 id uuid primary key, session_id uuid not null references live_streams.sessions(id) on delete cascade,
 actor_id uuid not null, auth_session_id uuid not null, action text not null check(action in ('start','stop','scene')),
 payload jsonb not null, status text not null default 'queued' check(status in ('queued','processing','accepted','failed')),
 lease_id uuid, lease_until timestamptz, result jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index live_controls_session on live_streams.controls(session_id,created_at desc,id desc);
create unique index live_control_pending on live_streams.controls(session_id) where status in ('queued','processing');
create table live_streams.gift_intents (
 order_id uuid primary key, session_id uuid not null references live_streams.sessions(id) on delete cascade,
 created_at timestamptz not null default now()
);
create table live_streams.notification_jobs (
 session_id uuid not null references live_streams.sessions(id) on delete cascade, kind text not null check(kind in ('reminder','live')),
 due_at timestamptz not null, cutoff_at timestamptz not null default now(), cursor_id uuid, completed_at timestamptz,
 primary key(session_id,kind)
);
create index live_notification_due on live_streams.notification_jobs(due_at,session_id) where completed_at is null;
create table live_streams.notification_receipts (
 session_id uuid not null references live_streams.sessions(id) on delete cascade, kind text not null,
 user_id uuid not null references public.profiles(id) on delete cascade, notification_id uuid not null default gen_random_uuid(),
 created_at timestamptz not null default now(), primary key(session_id,kind,user_id)
);
create table live_streams.provider_outbox (
 id uuid primary key default gen_random_uuid(), session_id uuid not null references live_streams.sessions(id) on delete cascade,
 action text not null check(action in ('eject','stop')), provider_identity uuid,
 state text not null default 'pending' check(state in ('pending','leased','done','dead')), available_at timestamptz not null default now(),
 lease_id uuid, lease_until timestamptz, attempts integer not null default 0, created_at timestamptz not null default now(), last_error text
);
create index live_provider_outbox_due on live_streams.provider_outbox(available_at,id) where state in ('pending','leased');
create table live_streams.cover_uploads (
 object_path text primary key, session_id uuid not null references live_streams.sessions(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade, request_id uuid not null,
 created_at timestamptz not null default now(), finalized_at timestamptz, unique(user_id,request_id)
);
create index live_cover_uploads_user on live_streams.cover_uploads(user_id,created_at);
create index live_cover_uploads_session on live_streams.cover_uploads(session_id);

do $$ declare t record; begin
 for t in select tablename from pg_tables where schemaname='live_streams' loop
  execute format('alter table live_streams.%I enable row level security',t.tablename);
  execute format('revoke all on live_streams.%I from public,anon,authenticated,service_role',t.tablename);
 end loop;
end $$;




-- Live-owned compatibility boundary. Existing account/security systems are
-- consulted when installed; this never creates substitutes for those systems.
create or replace function live_streams.account_available(p_user uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare permitted boolean;
begin
 select exists(select 1 from auth.users u join public.profiles p on p.id=u.id
  where u.id=p_user and u.deleted_at is null and not coalesce(u.is_anonymous,false)
  and (u.banned_until is null or u.banned_until<=now()) and p.deactivated_at is null
  and (p.restricted_until is null or p.restricted_until<=now())) into permitted;
 if not permitted then return false;end if;
 if to_regclass('admin_ops.staff_social_shells') is not null then
  execute 'select not exists(select 1 from admin_ops.staff_social_shells where user_id=$1)' into permitted using p_user;
  if not permitted then return false;end if;
 end if;
 if to_regclass('account_erasure.jobs') is not null then
  execute 'select not exists(select 1 from account_erasure.jobs where user_id=$1 and state<>''completed'')' into permitted using p_user;
  if not permitted then return false;end if;
 end if;
 return true;
end $$;
create or replace function live_streams.business_actor(p_user uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare business boolean;
begin
 select exists(select 1 from public.profiles where id=p_user and account_type='business') into business;
 if not business and to_regclass('business_auth.accounts') is not null then
  execute 'select exists(select 1 from business_auth.accounts where business_id=$1)' into business using p_user;
 end if;
 return business;
end $$;
create or replace function live_streams.business_session_valid(p_user uuid,p_session uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare permitted boolean;
begin
 if not live_streams.business_actor(p_user) then return true;end if;
 if to_regnamespace('business_auth') is not null then
  -- An installed but incomplete stronger guard is an error, never a fallback.
  execute 'select business_auth.session_allowed($1,$2)' into permitted using p_user,p_session;
  return coalesce(permitted,false);
 end if;
 -- The deployed production Studio binds access members to Auth sessions.
 -- Live requires that binding even when the legacy Studio has an owner default.
 return exists(select 1 from public.studio_session_members sm
  join public.business_access_members m on m.id=sm.member_id and m.business_id=sm.business_id
  where sm.session_id=p_session::text and sm.business_id=p_user and m.active);
end $$;
create or replace function live_streams.active_user(p_user uuid,p_session uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select live_streams.account_available(p_user) and live_streams.business_session_valid(p_user,p_session)
  and exists(select 1 from auth.sessions where id=p_session and user_id=p_user
    and (not_after is null or not_after>now()));
$$;
create or replace function live_streams.publisher_allowed(p_user uuid,p_session uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select live_streams.active_user(p_user,p_session) and (not live_streams.business_actor(p_user)
  or exists(select 1 from public.studio_session_members sm
   join public.business_access_members m on m.id=sm.member_id and m.business_id=sm.business_id
   where sm.session_id=p_session::text and sm.business_id=p_user and m.active and m.role in ('owner','admin','editor')));
$$;
create or replace function live_streams.require_user() returns uuid
language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();sid uuid;permitted boolean;
begin
 begin sid:=(auth.jwt()->>'session_id')::uuid;exception when others then raise exception 'AUTH_REQUIRED' using errcode='42501';end;
 if uid is null or sid is null or not live_streams.active_user(uid,sid) then
  raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 if to_regprocedure('public.business_session_allowed()') is not null then
  execute 'select public.business_session_allowed()' into permitted;
  if not coalesce(permitted,false) then raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 end if;
 return uid;
end $$;
revoke all on function live_streams.account_available(uuid),live_streams.business_actor(uuid),
 live_streams.business_session_valid(uuid,uuid),live_streams.active_user(uuid,uuid),
 live_streams.publisher_allowed(uuid,uuid),live_streams.require_user()
 from public,anon,authenticated,service_role;

create function live_streams.require_publisher() returns uuid language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=live_streams.require_user();
begin
 if not live_streams.publisher_allowed(uid,(auth.jwt()->>'session_id')::uuid) then raise exception 'PUBLISHER_ACCESS_DENIED' using errcode='42501';end if;
 return uid;
end $$;
create function live_streams.staff_role(p_user uuid) returns text language sql stable security definer set search_path='' as $$
 select role from public.admin_users where user_id=p_user and active;
$$;
create function live_streams.require_admin(p_moderate boolean default false) returns text language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); r text:=live_streams.staff_role(uid);sid uuid:=(auth.jwt()->>'session_id')::uuid;
begin
 if r is null or not r=any(case when p_moderate then array['super_admin','platform_admin','trust_safety']
  else array['super_admin','platform_admin','trust_safety','ops_engineer','analyst','auditor_readonly','finance_admin'] end)
  or not exists(select 1 from auth.users u join auth.sessions s on s.user_id=u.id where u.id=uid and s.id=sid and u.deleted_at is null
   and (u.banned_until is null or u.banned_until<=now()) and (s.not_after is null or s.not_after>now()))
  or not public.triniti_admin_session_check(uid,sid) then raise exception 'ADMIN_ACCESS_DENIED' using errcode='42501';end if;
 return r;
end $$;
create function live_streams.role_for(p_session uuid,p_user uuid) returns text language sql stable security definer set search_path='' as $$
 select case when s.host_id=p_user then 'host' else coalesce((select m.role from live_streams.members m where m.session_id=s.id and m.user_id=p_user and m.status='accepted'),'viewer') end
 from live_streams.sessions s where s.id=p_session;
$$;
create function live_streams.can_view(p_session uuid,p_user uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from live_streams.sessions s join public.profiles p on p.id=s.host_id join auth.users u on u.id=s.host_id
 where s.id=p_session and p_user is not null and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now())
 and (p.restricted_until is null or p.restricted_until<=now())
 and live_streams.account_available(s.host_id)
 and not exists(select 1 from live_streams.exclusions x where x.session_id=s.id and x.user_id=p_user)
 and not exists(select 1 from public.blocked_users b where (b.blocker_id=p_user and b.blocked_id=s.host_id) or (b.blocker_id=s.host_id and b.blocked_id=p_user))
 and (s.host_id=p_user or exists(select 1 from live_streams.members m where m.session_id=s.id and m.user_id=p_user and m.status in ('invited','accepted'))
  or (s.state in ('scheduled','starting','live','reconnecting','ending','ended') and (s.audience='public'
   or (s.audience='followers' and exists(select 1 from public.follows f where f.follower_id=p_user and f.following_id=s.host_id))))));
$$;
create function live_streams.profile_json(p_user uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p.id,'username',p.username,'full_name',p.full_name,'avatar_url',p.avatar_url,'is_verified',p.is_verified) from public.profiles p where p.id=p_user;
$$;
create function live_streams.session_json(p_session uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select (to_jsonb(s)-'pinned_message_id'-'chat_epoch'-'cover_object_path')||jsonb_build_object('host',live_streams.profile_json(s.host_id),'has_cover',s.cover_object_path is not null) from live_streams.sessions s where s.id=p_session;
$$;
create function live_streams.message_json(p_message uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',m.id,'session_id',m.session_id,'user_id',m.user_id,'body',case when m.removed then '' else m.body end,
  'created_at',m.created_at,'removed',m.removed,'author',live_streams.profile_json(m.user_id),'role',live_streams.role_for(m.session_id,m.user_id))
 from live_streams.messages m where m.id=p_message;
$$;
create function live_streams.capabilities(p_session uuid default null) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('create',c.create_enabled,'broadcast',c.stage_enabled and c.delivery_enabled and (s.id is null or s.audience='public' or c.private_delivery_enabled),
  'view',c.delivery_enabled and (s.id is null or s.audience='public' or c.private_delivery_enabled),'chat',c.chat_enabled,'gifts',false,
  'recording',c.recording_enabled,'captions',false,'multi_camera',c.stage_enabled,'screen_share',c.stage_enabled,'reminders',c.reminders_enabled,
  'reason',case when not c.stage_enabled or not c.delivery_enabled then 'broadcast_setup_pending' else null end,
  'max_stage_members',c.max_stage_members,'max_chat_history',150)
 from live_streams.settings c left join live_streams.sessions s on s.id=p_session where c.singleton;
$$;
create function live_streams.take_rate(p_scope text,p_key text,p_limit integer,p_seconds integer) returns void language plpgsql security definer set search_path='' as $$
declare bucket timestamptz:=to_timestamp(floor(extract(epoch from clock_timestamp())/p_seconds)*p_seconds);total integer;
begin
 insert into live_streams.rate_limits(scope,key,window_start,count) values(p_scope,p_key,bucket,1)
 on conflict(scope,key,window_start) do update set count=live_streams.rate_limits.count+1 returning count into total;
 if total>p_limit then raise exception 'RATE_LIMIT' using errcode='P0001';end if;
end $$;
create function live_streams.broadcast(p_session uuid,p_event text,p_payload jsonb) returns void language plpgsql security definer set search_path='' as $$
declare epoch uuid;control_payload jsonb;
begin
 -- Live payloads are narrow, server-authored and never include credentials.
 if to_regprocedure('realtime.send(jsonb,text,text,boolean)') is not null then
  select chat_epoch into epoch from live_streams.sessions where id=p_session;
  if epoch is null then return;end if;
  perform realtime.send(p_payload,p_event,'live:'||p_session::text||':'||epoch::text,true);
  if p_event in ('session','access_changed','warning') then
   control_payload:=case when p_event='session' then jsonb_build_object('session',jsonb_build_object('id',p_session,'state',p_payload->'session'->>'state','updated_at',p_payload->'session'->>'updated_at'))
    else jsonb_build_object('session_id',p_session,'user_id',p_payload->>'user_id') end;
   perform realtime.send(control_payload,p_event,'live-control:'||p_session::text,true);
  end if;
 end if;
end $$;

create function live_streams.provider_access(p_session uuid,p_purpose text) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();s live_streams.sessions;cfg live_streams.settings;role text;provider_id uuid;admin boolean:=false;
begin
 if p_purpose='playback' and live_streams.staff_role(uid) is not null then perform live_streams.require_admin(false);admin:=true;
 else uid:=live_streams.require_user();end if;
 select * into cfg from live_streams.settings where singleton;
 select * into s from live_streams.sessions where id=p_session;if not found then raise exception 'LIVE_NOT_AVAILABLE';end if;
 role:=live_streams.role_for(p_session,uid);
 if not live_streams.can_view(p_session,uid) then
  if p_purpose<>'playback' then raise exception 'ACCESS_DENIED';end if;
  perform live_streams.require_admin(false);admin:=true;
 end if;
 if p_purpose='stage' then
  perform live_streams.require_publisher();
  if not cfg.stage_enabled then raise exception 'PROVIDER_NOT_READY';end if;
  if role not in ('host','producer','camera','guest') or s.state not in ('draft','scheduled','backstage','starting','live','reconnecting') then raise exception 'ACCESS_DENIED';end if;
  perform live_streams.take_rate('stage_token',uid::text,10,60);
  if role='host' then provider_id:=uid;else select provider_identity into provider_id from live_streams.members where session_id=p_session and user_id=uid and status='accepted';end if;
  if provider_id is null then raise exception 'ACCESS_DENIED';end if;
  update live_streams.sessions set state='backstage',updated_at=now() where id=p_session and state='draft';
 elsif p_purpose='playback' then
  if not cfg.delivery_enabled or (s.audience<>'public' and not cfg.private_delivery_enabled) then raise exception 'DELIVERY_NOT_READY';end if;
  if s.state not in ('live','reconnecting') and not (s.state='ended' and s.replay_available) then raise exception 'LIVE_NOT_AVAILABLE';end if;
 else raise exception 'INVALID_PURPOSE';end if;
 return jsonb_build_object('session_id',p_session,'actor_id',uid,'auth_session_id',(auth.jwt()->>'session_id')::uuid,'role',role,'provider_identity',provider_id,
  'max_stage_members',cfg.max_stage_members,'profile',live_streams.profile_json(uid),'state',s.state,'audience',s.audience,'admin',admin);
end $$;

create function live_streams.prepare_control(p_session uuid,p_action text,p_request uuid,p_scene jsonb,p_reason text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();sid uuid:=(auth.jwt()->>'session_id')::uuid;s live_streams.sessions;c live_streams.controls;cfg live_streams.settings;role text;payload jsonb;
begin
 if p_request is null or p_action not in ('start','stop','scene') then raise exception 'INVALID_CONTROL';end if;
 role:=live_streams.role_for(p_session,uid);
 if role not in ('host','producer') then
  if p_action<>'stop' then raise exception 'ACCESS_DENIED';end if;
  perform live_streams.require_admin(true);
  if nullif(btrim(p_reason),'') is null or length(p_reason)>1000 then raise exception 'REASON_REQUIRED';end if;
 else
  uid:=live_streams.require_publisher();
  if not live_streams.can_view(p_session,uid) then raise exception 'ACCESS_DENIED';end if;
 end if;
 if p_action='scene' and (jsonb_typeof(p_scene) is distinct from 'object' or p_scene->>'preset' not in ('host','grid','interview','game','screen') or octet_length(p_scene::text)>2048) then raise exception 'INVALID_SCENE';end if;
 payload:=jsonb_build_object('scene',coalesce(p_scene,'{"preset":"host"}'::jsonb),'reason',p_reason);
 perform pg_advisory_xact_lock(hashtextextended('live-control:'||uid::text||p_request::text,0));
 select * into c from live_streams.controls where id=p_request;
 if found then
  if (c.actor_id,c.session_id,c.action,c.payload) is distinct from (uid,p_session,p_action,payload) then raise exception 'IDEMPOTENCY_CONFLICT';end if;
  return jsonb_build_object('operation_id',c.id,'status',c.status,'result',c.result);
 end if;
 -- Global admission serializes broadcast starts only. Viewing/chat never touch it.
 if p_action='start' then perform pg_advisory_xact_lock(812611,1);end if;
 select * into cfg from live_streams.settings where singleton;
 select * into s from live_streams.sessions where id=p_session for update;if not found then raise exception 'LIVE_NOT_AVAILABLE';end if;
 if p_action='start' then
  if not cfg.stage_enabled or not cfg.delivery_enabled or (s.audience<>'public' and not cfg.private_delivery_enabled) or (s.recording_enabled and not cfg.recording_enabled) then raise exception 'BROADCAST_NOT_READY';end if;
  if s.state not in ('draft','scheduled','backstage') then raise exception 'STATE_CONFLICT';end if;
  if (select count(*) from (select 1 from live_streams.sessions where state in ('starting','live','reconnecting','ending') limit cfg.max_active_broadcasts) t)>=cfg.max_active_broadcasts then raise exception 'BROADCAST_CAPACITY_REACHED';end if;
 elsif p_action='scene' then
  if s.state<>'live' then raise exception 'STATE_CONFLICT';end if;
 elsif s.state in ('ended','cancelled') then return jsonb_build_object('operation_id',p_request,'status','accepted','result',jsonb_build_object('ok',true,'session_id',p_session,'state',s.state));
 end if;
 perform live_streams.take_rate('control',uid::text,30,60);
 insert into live_streams.controls(id,session_id,actor_id,auth_session_id,action,payload) values(p_request,p_session,uid,sid,p_action,payload);
 if p_action='start' then update live_streams.provider_sessions set authority_actor_id=uid,authority_session_id=sid where session_id=p_session;end if;
 update live_streams.sessions set state=case p_action when 'start' then 'starting' when 'stop' then 'ending' else state end,updated_at=now() where id=p_session;
 insert into live_streams.audit(session_id,actor_id,action,reason,payload) values(p_session,uid,'broadcast_'||p_action,p_reason,payload);
 perform live_streams.broadcast(p_session,'session',jsonb_build_object('session',live_streams.session_json(p_session)));
 return jsonb_build_object('operation_id',p_request,'status','queued','result',null);
end $$;

create function live_streams.service_context(p_session uuid,p_actor uuid,p_auth_session uuid,p_purpose text,p_operation uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s live_streams.sessions;ps live_streams.provider_sessions;c live_streams.controls;cfg live_streams.settings;role text;member_id uuid;allowed jsonb;lease uuid;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED' using errcode='42501';end if;
 if not live_streams.active_user(p_actor,p_auth_session) and not (
  p_purpose in ('playback','control','control_check') and live_streams.staff_role(p_actor) is not null
  and public.triniti_admin_session_check(p_actor,p_auth_session)
  and exists(select 1 from auth.users u join auth.sessions a on a.user_id=u.id where u.id=p_actor and a.id=p_auth_session and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) and (a.not_after is null or a.not_after>now()))
 ) then raise exception 'AUTH_REQUIRED';end if;
 select * into s from live_streams.sessions where id=p_session;
 select * into ps from live_streams.provider_sessions where session_id=p_session;
 select * into cfg from live_streams.settings where singleton;
 if s.id is null or ps.session_id is null then raise exception 'LIVE_NOT_AVAILABLE';end if;
 role:=live_streams.role_for(p_session,p_actor);
 if not live_streams.can_view(p_session,p_actor) and not (p_purpose in ('playback','control','control_check') and live_streams.staff_role(p_actor) in ('super_admin','platform_admin','trust_safety','ops_engineer','analyst','auditor_readonly','finance_admin') and public.triniti_admin_session_check(p_actor,p_auth_session)) then raise exception 'ACCESS_DENIED';end if;
 if p_purpose='stage' then
  if not live_streams.publisher_allowed(p_actor,p_auth_session) then raise exception 'ACCESS_DENIED';end if;
  if not cfg.stage_enabled or role not in ('host','producer','camera','guest') or s.state not in ('backstage','scheduled','starting','live','reconnecting') then raise exception 'ACCESS_DENIED';end if;
  if role='host' then member_id:=p_actor;else select provider_identity into member_id from live_streams.members where session_id=p_session and user_id=p_actor and status='accepted';end if;
  if member_id is null then raise exception 'ACCESS_DENIED';end if;
  insert into live_streams.stage_grants(session_id,user_id,auth_session_id,provider_identity,expires_at)
  values(p_session,p_actor,p_auth_session,member_id,now()+interval '6 hours')
  on conflict(session_id,user_id,auth_session_id,provider_identity) do update set expires_at=excluded.expires_at,revoked_at=null;
 elsif p_purpose='playback' then
  if not cfg.delivery_enabled or (s.audience<>'public' and not cfg.private_delivery_enabled) or (s.state not in ('live','reconnecting') and not (s.state='ended' and s.replay_available)) then raise exception 'LIVE_NOT_AVAILABLE';end if;
 elsif p_purpose in ('control','control_check') then
  select * into c from live_streams.controls where id=p_operation and session_id=p_session and actor_id=p_actor and auth_session_id=p_auth_session for update;
  if not found then raise exception 'CONTROL_NOT_FOUND';end if;
  if role not in ('host','producer') and not (c.action='stop' and live_streams.staff_role(p_actor) in ('super_admin','platform_admin','trust_safety') and public.triniti_admin_session_check(p_actor,p_auth_session)) then raise exception 'ACCESS_DENIED';end if;
  if role in ('host','producer') and not live_streams.publisher_allowed(p_actor,p_auth_session) then raise exception 'ACCESS_DENIED';end if;
  if p_purpose='control_check' then
   if c.status<>'processing' or c.lease_until<=clock_timestamp() then raise exception 'CONTROL_LEASE_EXPIRED';end if;
   lease:=c.lease_id;
  else
  if c.status='accepted' then return jsonb_build_object('completed',true,'result',c.result);end if;
  if c.status='processing' and c.lease_until>clock_timestamp() then raise exception 'CONTROL_IN_PROGRESS';end if;
  if c.status='failed' then raise exception 'CONTROL_FAILED';end if;
  lease:=gen_random_uuid();
  update live_streams.controls set status='processing',lease_id=lease,lease_until=clock_timestamp()+interval '45 seconds',updated_at=now() where id=c.id;
  end if;
 else raise exception 'INVALID_PURPOSE';end if;
 select coalesce(jsonb_agg(v),'[]') into allowed from (
  select s.host_id::text as provider_identity,'host'::text as role,s.host_id as user_id
   where exists(select 1 from live_streams.stage_grants g where g.session_id=p_session and g.user_id=s.host_id and g.provider_identity=s.host_id
    and g.revoked_at is null and g.expires_at>now() and live_streams.publisher_allowed(g.user_id,g.auth_session_id))
  union all select m.provider_identity::text,m.role,m.user_id from live_streams.members m
   join public.profiles p on p.id=m.user_id join auth.users u on u.id=p.id
   where m.session_id=p_session and m.status='accepted' and m.role in ('producer','camera','guest')
    and exists(select 1 from live_streams.stage_grants g where g.session_id=p_session and g.user_id=m.user_id and g.provider_identity=m.provider_identity
     and g.revoked_at is null and g.expires_at>now() and live_streams.publisher_allowed(g.user_id,g.auth_session_id))
    and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now())
    and (p.restricted_until is null or p.restricted_until<=now()) and live_streams.can_view(p_session,m.user_id)
    and live_streams.account_available(m.user_id)
    and not exists(select 1 from live_streams.exclusions x where x.session_id=p_session and x.user_id=m.user_id)
 ) v;
 return jsonb_build_object('session_id',s.id,'state',s.state,'host_id',s.host_id,'audience',s.audience,'recording_enabled',s.recording_enabled,
  'room_name',ps.room_name,'instance_id',ps.instance_id,'playback_path',case when s.state='ended' then ps.replay_path else 'live/'||s.id::text||'/'||ps.instance_id::text||'/master.m3u8' end,
  'role',role,'provider_identity',member_id,'allowed_participants',allowed,'max_stage_members',cfg.max_stage_members,
  'action',c.action,'payload',c.payload,'lease_id',lease,'active_scene',ps.active_scene);
end $$;

create function live_streams.finish_control(p_operation uuid,p_lease uuid,p_accepted boolean,p_error text,p_published jsonb default '[]') returns jsonb
language plpgsql security definer set search_path='' as $$
declare c live_streams.controls;result jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED' using errcode='42501';end if;
 select * into c from live_streams.controls where id=p_operation for update;
 if not found or c.lease_id is distinct from p_lease or c.status<>'processing' then raise exception 'CONTROL_LEASE_EXPIRED';end if;
 if p_accepted then
  result:=jsonb_build_object('ok',true,'session_id',c.session_id,'state',case when c.action='start' then 'starting' when c.action='stop' then 'ending' else 'live' end);
  update live_streams.controls set status='accepted',result=result,updated_at=now(),lease_until=null where id=c.id;
  if c.action in ('start','scene') then
   update live_streams.provider_sessions set active_scene=c.payload->'scene',published_participants=p_published,error=null where session_id=c.session_id;
  end if;
 else
  result:=jsonb_build_object('ok',false,'session_id',c.session_id,'state','unconfirmed');
  update live_streams.controls set status='failed',result=result,updated_at=now(),lease_until=null where id=c.id;
  update live_streams.provider_sessions set error=left(coalesce(p_error,'provider_operation_unconfirmed'),200) where session_id=c.session_id;
  -- A timeout may have reached the provider. Do not pretend it is offline or
  -- release the admission reservation until provider reconciliation confirms.
 end if;
 return result;
end $$;

create function live_streams.directory(p_filter text,p_topic text,p_state text,p_cursor jsonb,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=live_streams.require_user();lim integer:=greatest(1,least(coalesce(p_limit,24),24));items jsonb;next_cursor jsonb;ct timestamptz;ci uuid;
begin
 if p_filter not in ('for_you','following','followers','mine') or p_state not in ('live','scheduled','replay') then raise exception 'INVALID_FILTER';end if;
 if p_cursor is not null then ct:=(p_cursor->>'created_at')::timestamptz;ci:=(p_cursor->>'id')::uuid;if ct is null or ci is null then raise exception 'INVALID_CURSOR';end if;end if;
 with candidates as materialized (
  select s.id,s.created_at from live_streams.sessions s where
   (p_filter='mine' and (s.host_id=uid or exists(select 1 from live_streams.members m where m.session_id=s.id and m.user_id=uid and m.status in ('invited','accepted'))) or p_filter<>'mine' and (case p_state when 'live' then s.state in ('live','reconnecting') when 'scheduled' then s.state='scheduled' else s.state='ended' and s.replay_available end))
   and (p_topic is null or s.topic=p_topic) and (ct is null or (s.created_at,s.id)<(ct,ci))
   and (p_filter not in ('following','followers') or exists(select 1 from public.follows f where
    (p_filter='following' and f.follower_id=uid and f.following_id=s.host_id) or (p_filter='followers' and f.following_id=uid and f.follower_id=s.host_id)))
   and live_streams.can_view(s.id,uid) order by s.created_at desc,s.id desc limit lim+1
 ), page as(select * from candidates order by created_at desc,id desc limit lim)
 select coalesce((select jsonb_agg(live_streams.session_json(id)||jsonb_build_object('my_role',case when exists(select 1 from live_streams.sessions s where s.id=page.id and s.host_id=uid) then 'host' else coalesce((select m.role from live_streams.members m where m.session_id=page.id and m.user_id=uid and m.status<>'removed'),'viewer') end,
  'invitation_status',(select m.status from live_streams.members m where m.session_id=page.id and m.user_id=uid and m.status<>'removed')) order by created_at desc,id desc) from page),'[]'),
 case when (select count(*) from candidates)>lim then (select jsonb_build_object('created_at',created_at,'id',id) from page order by created_at,id limit 1) else null end
 into items,next_cursor;
 return jsonb_build_object('items',items,'next_cursor',next_cursor,'capabilities',live_streams.capabilities());
end $$;
create function live_streams.detail(p_session uuid,p_admin boolean default false) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();s live_streams.sessions;members jsonb:='[]';gifts jsonb:='[]';role text;
begin
 if p_admin then perform live_streams.require_admin(false);else uid:=live_streams.require_user();if not live_streams.can_view(p_session,uid) then raise exception 'LIVE_NOT_AVAILABLE' using errcode='42501';end if;end if;
 select * into s from live_streams.sessions where id=p_session;if not found then raise exception 'LIVE_NOT_AVAILABLE';end if;
 role:=live_streams.role_for(p_session,uid);
 if p_admin or role in ('host','producer','moderator') then
  select coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'status',m.status,'profile',live_streams.profile_json(m.user_id)) order by m.created_at,m.user_id),'[]') into members
  from (select * from live_streams.members where session_id=p_session and status<>'removed' order by created_at,user_id limit 50) m;
 end if;
 -- Paid gifts are deliberately deferred; no catalog or checkout is exposed.
 return jsonb_build_object('session',live_streams.session_json(p_session),'role',role,'capabilities',live_streams.capabilities(p_session),'gifts',gifts,'members',members,
  'reminded',exists(select 1 from live_streams.reminders where session_id=p_session and user_id=uid),'pinned_message',live_streams.message_json(s.pinned_message_id),
  'invitation',(select jsonb_build_object('role',m.role,'status',m.status) from live_streams.members m where m.session_id=p_session and m.user_id=uid and m.status in ('invited','accepted')),
  'chat_topic','live:'||s.id::text||':'||s.chat_epoch::text);
end $$;
create function live_streams.messages_page(p_session uuid,p_before jsonb,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();lim integer:=greatest(1,least(coalesce(p_limit,50),50));ct timestamptz;ci uuid;items jsonb;next_cursor jsonb;
begin
 if live_streams.staff_role(uid) is not null then perform live_streams.require_admin(false);else uid:=live_streams.require_user();if not live_streams.can_view(p_session,uid) then raise exception 'LIVE_NOT_AVAILABLE';end if;end if;
 if p_before is not null then ct:=(p_before->>'created_at')::timestamptz;ci:=(p_before->>'id')::uuid;if ct is null or ci is null then raise exception 'INVALID_CURSOR';end if;end if;
 with candidates as materialized(select m.id,m.created_at from live_streams.messages m where m.session_id=p_session and (ct is null or (m.created_at,m.id)<(ct,ci))
  and not exists(select 1 from public.blocked_users b where (b.blocker_id=uid and b.blocked_id=m.user_id) or (b.blocker_id=m.user_id and b.blocked_id=uid))
  order by m.created_at desc,m.id desc limit lim+1),page as(select * from candidates order by created_at desc,id desc limit lim)
 select coalesce((select jsonb_agg(live_streams.message_json(id) order by created_at,id) from page),'[]'),
  case when (select count(*) from candidates)>lim then (select jsonb_build_object('created_at',created_at,'id',id) from page order by created_at,id limit 1) else null end
 into items,next_cursor;
 return jsonb_build_object('items',items,'next_cursor',next_cursor);
end $$;

create function live_streams.command(p_action text,p_session uuid,p_payload jsonb,p_request uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare uid uuid:=auth.uid();s live_streams.sessions;c live_streams.commands;cfg live_streams.settings;
 role text;allowed text[];field text;result jsonb;sid uuid:=p_session;target uuid;msg uuid;reason text;scheduled timestamptz;is_admin boolean:=false;count_members integer;
begin
 if p_request is null or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>8192 then raise exception 'INVALID_COMMAND';end if;
 case p_action
 when 'create' then allowed:=array['title','description','topic','audience','scheduled_at','recording_enabled','language','thumbnail_url'];
 when 'update' then allowed:=array['title','description','topic','scheduled_at','recording_enabled','language','thumbnail_url'];
 when 'cancel','accept_invite' then allowed:='{}';
 when 'chat' then allowed:=array['body'];
 when 'reaction' then allowed:=array['reaction'];
 when 'report' then allowed:=array['reason','message_id'];
 when 'reminder' then allowed:=array['enabled'];
 when 'invite' then allowed:=array['user_id','role'];
 when 'remove_member' then allowed:=array['user_id'];
 when 'pin','remove_message' then allowed:=array['message_id'];
 when 'chat_settings' then allowed:=array['chat_mode','slow_mode_seconds'];
 when 'block_viewer' then allowed:=array['user_id','reason'];
 when 'gift_intent' then allowed:=array['product_id','expected_amount_minor'];
 when 'admin_warn' then allowed:=array['reason'];is_admin:=true;
 when 'admin_chat' then allowed:=array['reason','chat_mode','slow_mode_seconds'];is_admin:=true;
 when 'admin_remove_viewer' then allowed:=array['reason','user_id'];is_admin:=true;
 when 'admin_resolve_report' then allowed:=array['reason','report_id'];is_admin:=true;
 else raise exception 'INVALID_COMMAND';end case;
 for field in select jsonb_object_keys(p_payload) loop if not field=any(allowed) then raise exception 'INVALID_COMMAND_FIELD';end if;end loop;
 if is_admin then perform live_streams.require_admin(true);else uid:=live_streams.require_user();end if;
 if p_action in ('create','update','cancel','invite','remove_member','chat_settings','remove_message','pin','block_viewer') then perform live_streams.require_publisher();end if;
 if nullif(p_payload->>'thumbnail_url','') is not null then raise exception 'USE_PRIVATE_COVER_UPLOAD';end if;
 insert into live_streams.commands(actor_id,request_id,session_id,action,payload) values(uid,p_request,p_session,p_action,p_payload) on conflict do nothing;
 select * into c from live_streams.commands where actor_id=uid and request_id=p_request for update;
 if c.action<>p_action or c.session_id is distinct from p_session or c.payload<>p_payload then raise exception 'IDEMPOTENCY_CONFLICT';end if;
 if c.result is not null then return c.result||jsonb_build_object('duplicate',true);end if;
 select * into cfg from live_streams.settings where singleton;
 if p_action='create' then
  if not cfg.create_enabled then raise exception 'BROADCAST_NOT_READY';end if;
  perform live_streams.take_rate('create',uid::text,10,86400);
  if (select count(*) from (select 1 from live_streams.sessions where host_id=uid and state in ('draft','scheduled','backstage','starting','live','reconnecting','ending') limit 25) t)>=25 then raise exception 'SESSION_LIMIT';end if;
  scheduled:=nullif(p_payload->>'scheduled_at','')::timestamptz;
  if scheduled is not null and (scheduled<=now() or scheduled>now()+interval '366 days') then raise exception 'INVALID_SCHEDULE';end if;
  insert into live_streams.sessions(host_id,title,description,topic,audience,state,scheduled_at,recording_enabled,language,thumbnail_url)
  values(uid,btrim(p_payload->>'title'),coalesce(p_payload->>'description',''),p_payload->>'topic',coalesce(p_payload->>'audience','public'),
   case when scheduled is null then 'draft' else 'scheduled' end,scheduled,coalesce((p_payload->>'recording_enabled')::boolean,false),coalesce(p_payload->>'language','en'),nullif(p_payload->>'thumbnail_url','')) returning id into sid;
  insert into live_streams.provider_sessions(session_id,room_name) values(sid,'pc-live-'||replace(sid::text,'-',''));
  if scheduled is not null then insert into live_streams.notification_jobs(session_id,kind,due_at) values(sid,'reminder',greatest(now(),scheduled-interval '5 minutes'));end if;
 else
  if not is_admin and not live_streams.can_view(sid,uid) then raise exception 'LIVE_NOT_AVAILABLE' using errcode='42501';end if;
  -- Audience interactions do not acquire the hot session row lock.
  if p_action in ('chat','reaction','report','reminder','gift_intent') then
   select * into s from live_streams.sessions where id=sid;
  else select * into s from live_streams.sessions where id=sid for update;end if;
  if not found then raise exception 'LIVE_NOT_AVAILABLE';end if;
  role:=live_streams.role_for(sid,uid);
  if p_action in ('update','cancel','invite','remove_member') and role not in ('host','producer') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
  if p_action in ('chat_settings','remove_message','pin','block_viewer') and role not in ('host','producer','moderator') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
  if is_admin then reason:=nullif(btrim(p_payload->>'reason'),'');if reason is null or length(reason)>1000 then raise exception 'REASON_REQUIRED';end if;end if;
  case p_action
  when 'update' then
   if s.state not in ('draft','scheduled','backstage') then raise exception 'STATE_CONFLICT';end if;
   scheduled:=case when p_payload?'scheduled_at' then nullif(p_payload->>'scheduled_at','')::timestamptz else s.scheduled_at end;
   if scheduled is not null and (scheduled<=now() or scheduled>now()+interval '366 days') then raise exception 'INVALID_SCHEDULE';end if;
   update live_streams.sessions set title=case when p_payload?'title' then btrim(p_payload->>'title') else title end,
    description=coalesce(p_payload->>'description',description),topic=coalesce(p_payload->>'topic',topic),scheduled_at=scheduled,
    state=case when s.state='backstage' then 'backstage' when scheduled is not null then 'scheduled' else 'draft' end,
    recording_enabled=coalesce((p_payload->>'recording_enabled')::boolean,recording_enabled),language=coalesce(p_payload->>'language',language),
    thumbnail_url=case when p_payload?'thumbnail_url' then nullif(p_payload->>'thumbnail_url','') else thumbnail_url end,updated_at=now() where id=sid;
   if scheduled is not null then insert into live_streams.notification_jobs(session_id,kind,due_at) values(sid,'reminder',greatest(now(),scheduled-interval '5 minutes'))
    on conflict(session_id,kind) do update set due_at=excluded.due_at where live_streams.notification_jobs.completed_at is null;
   else delete from live_streams.notification_jobs where session_id=sid and kind='reminder' and completed_at is null;end if;
  when 'cancel' then
   if s.state not in ('draft','scheduled','backstage') then raise exception 'STATE_CONFLICT';end if;
   update live_streams.sessions set state='cancelled',ended_at=now(),updated_at=now() where id=sid;
  when 'chat' then
   if not cfg.chat_enabled or s.state not in ('live','reconnecting') then raise exception 'CHAT_CLOSED';end if;
   if (s.chat_mode='closed' or (s.chat_mode='followers' and not exists(select 1 from public.follows where follower_id=uid and following_id=s.host_id))) and role not in ('host','producer','moderator') then raise exception 'CHAT_CLOSED';end if;
   if nullif(btrim(p_payload->>'body'),'') is null or length(p_payload->>'body')>500 then raise exception 'INVALID_MESSAGE';end if;
   perform live_streams.take_rate('chat_user',uid::text,1,greatest(2,s.slow_mode_seconds));
   perform live_streams.take_rate('chat_room',sid::text,cfg.max_chat_messages_per_second,1);
   insert into live_streams.messages(id,session_id,user_id,body) values(p_request,sid,uid,btrim(p_payload->>'body'));
   result:=jsonb_build_object('ok',true,'session_id',sid,'message',live_streams.message_json(p_request));
   perform live_streams.broadcast(sid,'message',live_streams.message_json(p_request));
  when 'reaction' then
   if s.state<>'live' or p_payload->>'reaction' not in ('heart','applause','fire') then raise exception 'INVALID_REACTION';end if;
   perform live_streams.take_rate('reaction_user',uid::text,3,10);
   perform live_streams.take_rate('reaction_room',sid::text,5,1);
   perform live_streams.broadcast(sid,'reaction',jsonb_build_object('id',p_request,'reaction',p_payload->>'reaction'));
  when 'report' then
   perform live_streams.take_rate('report',uid::text,10,3600);
   msg:=nullif(p_payload->>'message_id','')::uuid;
   if msg is not null and not exists(select 1 from live_streams.messages where id=msg and session_id=sid) then raise exception 'INVALID_MESSAGE';end if;
   insert into live_streams.reports(id,session_id,reporter_id,message_id,reason) values(p_request,sid,uid,msg,btrim(p_payload->>'reason'));
  when 'reminder' then
   if not cfg.reminders_enabled then raise exception 'REMINDERS_NOT_READY';end if;
   if s.state<>'scheduled' then raise exception 'STATE_CONFLICT';end if;
   if jsonb_typeof(p_payload->'enabled') is distinct from 'boolean' then raise exception 'INVALID_REMINDER';end if;
   perform live_streams.take_rate('reminder',uid::text,30,60);
   if (p_payload->>'enabled')::boolean then insert into live_streams.reminders(session_id,user_id) values(sid,uid) on conflict do nothing;
   else delete from live_streams.reminders where session_id=sid and user_id=uid;end if;
  when 'invite' then
   if s.state in ('ended','ending','cancelled') then raise exception 'STATE_CONFLICT';end if;
   target:=(p_payload->>'user_id')::uuid;
   if target is null or target=s.host_id or p_payload->>'role' not in ('producer','camera','guest','moderator','viewer') then raise exception 'INVALID_MEMBER';end if;
   if role='producer' and p_payload->>'role'='producer' then raise exception 'ACCESS_DENIED';end if;
   if not exists(select 1 from public.profiles p join auth.users u on u.id=p.id where p.id=target and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()))
    or exists(select 1 from public.blocked_users b where (b.blocker_id=uid and b.blocked_id=target) or (b.blocker_id=target and b.blocked_id=uid)) then raise exception 'MEMBER_NOT_AVAILABLE';end if;
   select count(*) into count_members from live_streams.members where session_id=sid and status<>'removed' and role in ('producer','camera','guest') and user_id<>target;
   if p_payload->>'role' in ('producer','camera','guest') and count_members>=cfg.max_stage_members-1 then raise exception 'STAGE_FULL';end if;
   if (select count(*) from live_streams.members where session_id=sid and status<>'removed' and user_id<>target)>=49 then raise exception 'MEMBER_LIMIT';end if;
   insert into live_streams.provider_outbox(session_id,action,provider_identity) select sid,'eject',provider_identity from live_streams.members where session_id=sid and user_id=target and status='accepted';
   insert into live_streams.members(session_id,user_id,role) values(sid,target,p_payload->>'role')
    on conflict(session_id,user_id) do update set role=excluded.role,status='invited',provider_identity=gen_random_uuid();
  when 'accept_invite' then
   if s.state in ('ended','ending','cancelled') then raise exception 'STATE_CONFLICT';end if;
   update live_streams.members set status='accepted' where session_id=sid and user_id=uid and status='invited';
   if not found then raise exception 'INVITE_NOT_AVAILABLE';end if;
  when 'remove_member' then
   target:=(p_payload->>'user_id')::uuid;
   if target is null or target=s.host_id or (role='producer' and exists(select 1 from live_streams.members where session_id=sid and user_id=target and role='producer')) then raise exception 'ACCESS_DENIED';end if;
   insert into live_streams.provider_outbox(session_id,action,provider_identity) select sid,'eject',provider_identity from live_streams.members where session_id=sid and user_id=target and status='accepted';
   update live_streams.members set status='removed',provider_identity=gen_random_uuid() where session_id=sid and user_id=target;
   update live_streams.sessions set chat_epoch=gen_random_uuid() where id=sid;
   perform live_streams.broadcast(sid,'access_changed',jsonb_build_object('user_id',target));
  when 'chat_settings','admin_chat' then
   update live_streams.sessions set chat_mode=coalesce(p_payload->>'chat_mode',chat_mode),slow_mode_seconds=coalesce((p_payload->>'slow_mode_seconds')::integer,slow_mode_seconds),updated_at=now() where id=sid;
  when 'pin' then
   msg:=nullif(p_payload->>'message_id','')::uuid;
   if msg is not null and not exists(select 1 from live_streams.messages where id=msg and session_id=sid and not removed) then raise exception 'INVALID_MESSAGE';end if;
   update live_streams.sessions set pinned_message_id=msg,updated_at=now() where id=sid;
   perform live_streams.broadcast(sid,'pin',jsonb_build_object('message',live_streams.message_json(msg)));
  when 'remove_message' then
   msg:=(p_payload->>'message_id')::uuid;
   update live_streams.messages set removed=true where id=msg and session_id=sid;
   if not found then raise exception 'INVALID_MESSAGE';end if;
   update live_streams.sessions set pinned_message_id=null where id=sid and pinned_message_id=msg;
   perform live_streams.broadcast(sid,'message_removed',jsonb_build_object('id',msg));
  when 'block_viewer','admin_remove_viewer' then
   target:=(p_payload->>'user_id')::uuid;reason:=nullif(btrim(p_payload->>'reason'),'');
   if target is null or target=s.host_id or target=uid or reason is null then raise exception 'INVALID_REMOVAL';end if;
   if not is_admin and live_streams.role_for(sid,target) in ('host','producer','moderator') then raise exception 'ACCESS_DENIED';end if;
   insert into live_streams.exclusions(session_id,user_id,actor_id,reason) values(sid,target,uid,reason)
    on conflict(session_id,user_id) do update set actor_id=excluded.actor_id,reason=excluded.reason;
   insert into live_streams.provider_outbox(session_id,action,provider_identity) select sid,'eject',provider_identity from live_streams.members where session_id=sid and user_id=target and status='accepted';
   update live_streams.members set status='removed',provider_identity=gen_random_uuid() where session_id=sid and user_id=target;
   update live_streams.sessions set chat_epoch=gen_random_uuid() where id=sid;
   perform live_streams.broadcast(sid,'access_changed',jsonb_build_object('user_id',target));
  when 'admin_resolve_report' then
   target:=(p_payload->>'report_id')::uuid;
   update live_streams.reports set state='resolved',resolved_by=uid,resolution=reason where id=target and session_id=sid;
   if not found then raise exception 'REPORT_NOT_FOUND';end if;
  when 'admin_warn' then
   perform live_streams.broadcast(sid,'warning',jsonb_build_object('reason',reason));
  when 'gift_intent' then
   -- Existing finance only supports test capture. Production live gifts stay
   -- closed until a real provider/store-billing adapter is independently accepted.
   raise exception 'PAYMENTS_NOT_READY';
  else raise exception 'INVALID_COMMAND';end case;
 end if;
 if result is null then result:=jsonb_build_object('ok',true,'session_id',sid);end if;
 update live_streams.commands set result=result where actor_id=uid and request_id=p_request;
 if p_action not in ('chat','reaction','reminder') then
  insert into live_streams.audit(session_id,actor_id,action,reason,payload) values(sid,uid,p_action,reason,p_payload);
 end if;
 if p_action in ('create','update','cancel','chat_settings','admin_chat') then
  perform live_streams.broadcast(sid,'session',jsonb_build_object('session',live_streams.session_json(sid)));
 end if;
 return result;
end $$;

create function live_streams.admin_directory(p_state text,p_cursor jsonb,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare lim integer:=greatest(1,least(coalesce(p_limit,50),50));ct timestamptz;ci uuid;items jsonb;next_cursor jsonb;
begin
 perform live_streams.require_admin(false);
 if p_cursor is not null then ct:=(p_cursor->>'created_at')::timestamptz;ci:=(p_cursor->>'id')::uuid;if ct is null or ci is null then raise exception 'INVALID_CURSOR';end if;end if;
 with candidates as materialized(select id,created_at from live_streams.sessions where (p_state is null or state=p_state) and (ct is null or (created_at,id)<(ct,ci)) order by created_at desc,id desc limit lim+1),
 page as(select * from candidates order by created_at desc,id desc limit lim)
 select coalesce((select jsonb_agg(live_streams.session_json(id) order by created_at desc,id desc) from page),'[]'),
  case when (select count(*) from candidates)>lim then (select jsonb_build_object('created_at',created_at,'id',id) from page order by created_at,id limit 1) else null end into items,next_cursor;
 return jsonb_build_object('items',items,'next_cursor',next_cursor,'capabilities',live_streams.capabilities());
end $$;
create function live_streams.admin_detail(p_session uuid,p_audit_cursor jsonb,p_report_cursor jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r text:=live_streams.require_admin(false);d jsonb;reports jsonb;audit jsonb;ac jsonb;rc jsonb;ct timestamptz;ci uuid;
begin
 d:=live_streams.detail(p_session,true);
 ct:=(p_report_cursor->>'created_at')::timestamptz;ci:=(p_report_cursor->>'id')::uuid;
 with candidates as materialized(select * from live_streams.reports where session_id=p_session and (ct is null or (created_at,id)<(ct,ci)) order by created_at desc,id desc limit 26),page as(select * from candidates order by created_at desc,id desc limit 25)
 select coalesce((select jsonb_agg(to_jsonb(page) order by created_at desc,id desc) from page),'[]'),case when (select count(*) from candidates)>25 then (select jsonb_build_object('created_at',created_at,'id',id) from page order by created_at,id limit 1) else null end into reports,rc;
 ct:=(p_audit_cursor->>'created_at')::timestamptz;ci:=(p_audit_cursor->>'id')::uuid;
 with candidates as materialized(select * from live_streams.audit where session_id=p_session and (ct is null or (created_at,id)<(ct,ci)) order by created_at desc,id desc limit 26),page as(select * from candidates order by created_at desc,id desc limit 25)
 select coalesce((select jsonb_agg(to_jsonb(page) order by created_at desc,id desc) from page),'[]'),case when (select count(*) from candidates)>25 then (select jsonb_build_object('created_at',created_at,'id',id) from page order by created_at,id limit 1) else null end into audit,ac;
 return d||jsonb_build_object('reports',jsonb_build_object('items',reports,'next_cursor',rc),'audit',jsonb_build_object('items',audit,'next_cursor',ac),
  'permissions',jsonb_build_object('moderate',r in ('super_admin','platform_admin','trust_safety'),'finance',r in ('super_admin','finance_admin'),'configure',r in ('super_admin','platform_admin','ops_engineer')),
  'provider',(select jsonb_build_object('configured',cfg.stage_enabled and cfg.delivery_enabled,'last_event_at',ps.last_event_at,'error',ps.error) from live_streams.settings cfg left join live_streams.provider_sessions ps on ps.session_id=p_session where cfg.singleton));
end $$;

create function live_streams.provider_event(p_id text,p_instance uuid,p_type text,p_time timestamptz,p_digest text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ps live_streams.provider_sessions;s live_streams.sessions;prior live_streams.provider_events;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED' using errcode='42501';end if;
 if p_id is null or length(p_id)>200 or p_type not in ('streaming.started','streaming.updated','streaming.ended','streaming.error','streaming.warning')
  or p_time is null or p_time>clock_timestamp()+interval '1 minute' or p_digest !~ '^[0-9a-f]{64}$' then raise exception 'INVALID_PROVIDER_EVENT';end if;
 select * into ps from live_streams.provider_sessions where instance_id=p_instance for update;
 if not found then return jsonb_build_object('ok',true,'ignored',true);end if;
 select * into prior from live_streams.provider_events where event_id=p_id;
 if found then
  if (prior.session_id,prior.event_type,prior.event_time,prior.digest) is distinct from (ps.session_id,p_type,p_time,p_digest) then raise exception 'IDEMPOTENCY_CONFLICT';end if;
  return jsonb_build_object('ok',true,'duplicate',true);
 end if;
 insert into live_streams.provider_events(event_id,session_id,event_type,event_time,digest) values(p_id,ps.session_id,p_type,p_time,p_digest);
 select * into s from live_streams.sessions where id=ps.session_id for update;
 if (ps.last_event_at is not null and p_time<ps.last_event_at) or s.state in ('ended','cancelled') then return jsonb_build_object('ok',true,'ignored',true);end if;
 update live_streams.provider_sessions set last_event_at=p_time,error=case when p_type in ('streaming.error','streaming.warning') then p_type else null end where session_id=s.id;
 if p_type='streaming.started' and s.state='starting' then
  update live_streams.sessions set state='live',started_at=coalesce(started_at,p_time),updated_at=now() where id=s.id;
  update live_streams.provider_sessions set playback_path='live/'||s.id::text||'/'||ps.instance_id::text||'/master.m3u8' where session_id=s.id;
  insert into live_streams.notification_jobs(session_id,kind,due_at,cutoff_at) values(s.id,'live',now(),p_time) on conflict do nothing;
 elsif p_type='streaming.ended' then
  update live_streams.sessions set state='ended',ended_at=p_time,updated_at=now(),replay_available=s.recording_enabled and ps.playback_path is not null where id=s.id;
  update live_streams.provider_sessions set replay_path=case when s.recording_enabled then playback_path else null end where session_id=s.id;
 elsif p_type='streaming.error' and s.state in ('starting','live','reconnecting') then
  update live_streams.sessions set state='reconnecting',updated_at=now() where id=s.id;
  -- Stop ambiguous provider output before making a fresh broadcast. Durable
  -- worker retries until the provider confirms the stream has ended.
  insert into live_streams.provider_outbox(session_id,action) values(s.id,'stop');
 end if;
 perform live_streams.broadcast(s.id,'session',jsonb_build_object('session',live_streams.session_json(s.id)));
 return jsonb_build_object('ok',true,'session_id',s.id);
end $$;

create function live_streams.notification_batch(p_limit integer default 200) returns integer language plpgsql security definer set search_path='' as $$
declare j live_streams.notification_jobs;s live_streams.sessions;r record;lim integer:=greatest(1,least(coalesce(p_limit,200),500));sent integer:=0;scanned integer;last_uid uuid;nid uuid;
begin
 if not (select reminders_enabled from live_streams.settings where singleton) then return 0;end if;
 for j in select * from live_streams.notification_jobs where completed_at is null and due_at<=now() order by due_at,session_id for update skip locked limit 4 loop
  select * into s from live_streams.sessions where id=j.session_id;
  if (j.kind='reminder' and s.state not in ('scheduled','backstage')) or (j.kind='live' and s.state not in ('live','reconnecting')) then
   update live_streams.notification_jobs set completed_at=now() where session_id=j.session_id and kind=j.kind;continue;
  end if;
  scanned:=0;last_uid:=j.cursor_id;
  if j.kind='reminder' and j.cursor_id is null then j.cutoff_at:=clock_timestamp();update live_streams.notification_jobs set cutoff_at=j.cutoff_at where session_id=j.session_id and kind=j.kind;end if;
  for r in select candidates.user_id from (
   select m.user_id from live_streams.reminders m where m.session_id=j.session_id and m.created_at<=j.cutoff_at and (j.cursor_id is null or m.user_id>j.cursor_id)
   union
   select f.follower_id as user_id from public.follows f join public.profiles p on p.id=f.follower_id
    where j.kind='live' and f.following_id=s.host_id and f.created_at<=j.cutoff_at and p.notif_prefs->'updates' is distinct from 'false'::jsonb and p.notif_prefs->'all' is distinct from 'false'::jsonb and (j.cursor_id is null or f.follower_id>j.cursor_id)
  ) candidates order by candidates.user_id limit lim loop
   scanned:=scanned+1;last_uid:=r.user_id;
   if r.user_id=s.host_id or not live_streams.can_view(s.id,r.user_id) then continue;end if;
   if not exists(select 1 from public.profiles p join auth.users u on u.id=p.id where p.id=r.user_id and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) and p.notif_prefs->'updates' is distinct from 'false'::jsonb and p.notif_prefs->'all' is distinct from 'false'::jsonb) then continue;end if;
   nid:=null;
   insert into live_streams.notification_receipts(session_id,kind,user_id) values(j.session_id,j.kind,r.user_id) on conflict do nothing returning notification_id into nid;
   if nid is not null then
    insert into public.notifications(id,recipient_id,actor_id,type,message,body_preview,data)
    values(nid,r.user_id,s.host_id,'live_stream',case when j.kind='live' then 'A live stream you follow has started' else 'Your live stream reminder' end,
     left(s.title,120),jsonb_build_object('live_session_id',s.id,'screen','LiveStreams','sessionId',s.id,'kind',j.kind));sent:=sent+1;
   end if;
  end loop;
  update live_streams.notification_jobs set cursor_id=last_uid,completed_at=case when scanned<lim then now() else null end where session_id=j.session_id and kind=j.kind;
 end loop;
 return sent;
end $$;
create function live_streams.maintenance(p_limit integer default 1000) returns jsonb language plpgsql security definer set search_path='' as $$
declare lim integer:=greatest(1,least(coalesce(p_limit,1000),5000));messages integer;commands integer;rates integer;events integer;notifications integer;
 controls integer;outbox integer;grants integer;stopped integer:=0;revoked integer:=0;authority_row record;grant_row live_streams.stage_grants;
begin
 notifications:=live_streams.notification_batch(200);
 -- Auth revocation is checked against bound sessions, devices and current team
 -- roles. No audience member writes to these authority or provider rows.
 for grant_row in select * from live_streams.stage_grants where revoked_at is null and (checked_at is null or checked_at<now()-interval '45 seconds')
  order by checked_at nulls first,id for update skip locked limit lim loop
  update live_streams.stage_grants set checked_at=now() where id=grant_row.id;
  if grant_row.expires_at<=now() or not live_streams.publisher_allowed(grant_row.user_id,grant_row.auth_session_id)
   or not live_streams.can_view(grant_row.session_id,grant_row.user_id) or live_streams.role_for(grant_row.session_id,grant_row.user_id) not in ('host','producer','camera','guest') then
   update live_streams.stage_grants set revoked_at=now() where id=grant_row.id;
   insert into live_streams.provider_outbox(session_id,action,provider_identity) values(grant_row.session_id,'eject',grant_row.provider_identity);
   revoked:=revoked+1;
   if exists(select 1 from live_streams.provider_sessions ps where ps.session_id=grant_row.session_id
    and ps.published_participants @> jsonb_build_array(jsonb_build_object('provider_identity',grant_row.provider_identity::text))) then
    update live_streams.sessions set state='ending',updated_at=now() where id=grant_row.session_id and state in ('starting','live','reconnecting');
    insert into live_streams.provider_outbox(session_id,action) select grant_row.session_id,'stop'
     where not exists(select 1 from live_streams.provider_outbox where session_id=grant_row.session_id and action='stop' and state in ('pending','leased'));
    perform live_streams.broadcast(grant_row.session_id,'access_changed',jsonb_build_object('session_id',grant_row.session_id));
   end if;
  end if;
 end loop;
 for authority_row in select ps.session_id,ps.authority_actor_id,ps.authority_session_id,s.state,s.updated_at from live_streams.provider_sessions ps
  join live_streams.sessions s on s.id=ps.session_id where s.state in ('starting','live','reconnecting','ending')
  and (ps.authority_checked_at is null or ps.authority_checked_at<now()-interval '45 seconds')
  order by ps.authority_checked_at nulls first,ps.session_id for update of ps skip locked limit lim loop
  update live_streams.provider_sessions set authority_checked_at=now() where session_id=authority_row.session_id;
  if not coalesce(live_streams.publisher_allowed(authority_row.authority_actor_id,authority_row.authority_session_id),false)
   or not live_streams.can_view(authority_row.session_id,authority_row.authority_actor_id) or live_streams.role_for(authority_row.session_id,authority_row.authority_actor_id) not in ('host','producer')
   or authority_row.state='ending' and authority_row.updated_at<now()-interval '2 minutes'
   or authority_row.state='starting' and authority_row.updated_at<now()-interval '2 minutes' then
   update live_streams.sessions set state='ending',updated_at=case when state='ending' then updated_at else now() end where id=authority_row.session_id;
   insert into live_streams.provider_outbox(session_id,action) select authority_row.session_id,'stop'
    where not exists(select 1 from live_streams.provider_outbox where session_id=authority_row.session_id and action='stop'
     and (state in ('pending','leased') or created_at>now()-interval '2 minutes'));
   stopped:=stopped+1;
   perform live_streams.broadcast(authority_row.session_id,'session',jsonb_build_object('session',jsonb_build_object('id',authority_row.session_id,'state','ending','updated_at',now())));
  end if;
 end loop;
 with stale as(select id from live_streams.messages m where created_at<now()-interval '14 days'
  and not exists(select 1 from live_streams.sessions s where s.pinned_message_id=m.id)
  and not exists(select 1 from live_streams.reports r where r.message_id=m.id and r.state='open')
  order by created_at,id for update skip locked limit lim) delete from live_streams.messages m using stale where m.id=stale.id;get diagnostics messages=row_count;
 with stale as(select actor_id,request_id from live_streams.commands where created_at<now()-interval '7 days' order by created_at for update skip locked limit lim)
 delete from live_streams.commands c using stale where (c.actor_id,c.request_id)=(stale.actor_id,stale.request_id);get diagnostics commands=row_count;
 with stale as(select scope,key,window_start from live_streams.rate_limits where window_start<now()-interval '2 days' order by window_start for update skip locked limit lim)
 delete from live_streams.rate_limits r using stale where (r.scope,r.key,r.window_start)=(stale.scope,stale.key,stale.window_start);get diagnostics rates=row_count;
 with stale as(select event_id from live_streams.provider_events where created_at<now()-interval '30 days' order by created_at for update skip locked limit lim)
 delete from live_streams.provider_events e using stale where e.event_id=stale.event_id;get diagnostics events=row_count;
 with stale as(select c.id from live_streams.controls c join live_streams.sessions s on s.id=c.session_id where c.created_at<now()-interval '7 days'
  and s.state in ('ended','cancelled') order by c.created_at for update of c skip locked limit lim)
 delete from live_streams.controls c using stale where c.id=stale.id;get diagnostics controls=row_count;
 with stale as(select id from live_streams.provider_outbox where state='done' and created_at<now()-interval '7 days' order by created_at for update skip locked limit lim)
 delete from live_streams.provider_outbox o using stale where o.id=stale.id;get diagnostics outbox=row_count;
 with stale as(select id from live_streams.stage_grants where revoked_at is not null and created_at<now()-interval '7 days' order by created_at for update skip locked limit lim)
 delete from live_streams.stage_grants g using stale where g.id=stale.id;get diagnostics grants=row_count;
 return jsonb_build_object('messages_pruned',messages,'commands_pruned',commands,'rates_pruned',rates,'events_pruned',events,'notifications_created',notifications,
  'controls_pruned',controls,'outbox_pruned',outbox,'grants_pruned',grants,'stage_grants_revoked',revoked,'orphan_stops_queued',stopped);
end $$;
create function live_streams.claim_outbox(p_limit integer default 10) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED';end if;
 with claimed as(select id from live_streams.provider_outbox where state in ('pending','leased') and available_at<=now() and (lease_until is null or lease_until<=now()) and attempts<8
  order by available_at,id for update skip locked limit greatest(1,least(coalesce(p_limit,10),10))), updated as(
  update live_streams.provider_outbox o set state='leased',lease_id=gen_random_uuid(),lease_until=now()+interval '60 seconds',attempts=attempts+1
  from claimed where o.id=claimed.id returning o.*)
 select coalesce(jsonb_agg(to_jsonb(u)||jsonb_build_object('room_name',ps.room_name,'instance_id',ps.instance_id)),'[]') into result
 from updated u join live_streams.provider_sessions ps on ps.session_id=u.session_id;
 return jsonb_build_object('items',result);
end $$;
create function live_streams.finish_outbox(p_id uuid,p_lease uuid,p_ok boolean,p_error text) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED';end if;
 update live_streams.provider_outbox set state=case when p_ok then 'done' when attempts>=8 then 'dead' else 'pending' end,
  available_at=now()+make_interval(secs=>least(900,5*(2^attempts)::integer)),lease_until=null,last_error=case when p_ok then null else left(p_error,200) end
 where id=p_id and lease_id=p_lease and state='leased';
 if not found then raise exception 'OUTBOX_LEASE_EXPIRED';end if;
 return jsonb_build_object('ok',true);
end $$;

create function live_streams.can_receive(p_topic text) returns boolean language plpgsql stable security definer set search_path='' as $$
declare sid uuid;uid uuid;epoch uuid;
begin
 if p_topic !~ '^live:[0-9a-f-]{36}:[0-9a-f-]{36}$' and p_topic !~ '^live-control:[0-9a-f-]{36}$' then return false;end if;
 begin sid:=split_part(p_topic,':',2)::uuid;uid:=live_streams.require_user();exception when others then return false;end;
 if p_topic like 'live:%' then
  begin epoch:=split_part(p_topic,':',3)::uuid;exception when others then return false;end;
  if not exists(select 1 from live_streams.sessions where id=sid and chat_epoch=epoch) then return false;end if;
 end if;
 return live_streams.can_view(sid,uid);
end $$;

create function live_streams.cover_upload(p_session uuid,p_action text,p_path text,p_request uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=live_streams.require_publisher();asset live_streams.cover_uploads;new_path text;s live_streams.sessions;
begin
 select * into s from live_streams.sessions where id=p_session;
 if not found or not live_streams.can_view(p_session,uid) or live_streams.role_for(p_session,uid) not in ('host','producer') then raise exception 'ACCESS_DENIED';end if;
 if p_action='authorize' then
  if p_request is null then raise exception 'INVALID_REQUEST';end if;
  perform pg_advisory_xact_lock(hashtextextended('live-cover:'||uid::text||p_request::text,0));
  select * into asset from live_streams.cover_uploads where user_id=uid and request_id=p_request;
  if found then
   if asset.session_id<>p_session then raise exception 'IDEMPOTENCY_CONFLICT';end if;
   if asset.created_at<now()-interval '2 hours' then raise exception 'UPLOAD_EXPIRED';end if;
   return jsonb_build_object('bucket','live-covers','object_path',asset.object_path,'session_id',p_session,'finalized',asset.finalized_at is not null);
  end if;
  perform live_streams.take_rate('cover_upload',uid::text,10,3600);
  new_path:=uid::text||'/'||p_session::text||'/'||gen_random_uuid()::text||'.jpg';
  insert into live_streams.cover_uploads(object_path,session_id,user_id,request_id) values(new_path,p_session,uid,p_request);
 elsif p_action='inspect' then
  select * into asset from live_streams.cover_uploads where object_path=p_path and session_id=p_session and user_id=uid;
  if not found or asset.created_at<now()-interval '2 hours' and asset.finalized_at is null then raise exception 'UPLOAD_NOT_AVAILABLE';end if;
  new_path:=asset.object_path;
 else raise exception 'INVALID_COVER_ACTION';end if;
 return jsonb_build_object('bucket','live-covers','object_path',new_path,'session_id',p_session,'finalized',asset.finalized_at is not null);
end $$;
create function live_streams.cover_finalize(p_actor uuid,p_auth_session uuid,p_session uuid,p_path text,p_width integer,p_height integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare asset live_streams.cover_uploads;metadata jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED';end if;
 if not live_streams.publisher_allowed(p_actor,p_auth_session) or not live_streams.can_view(p_session,p_actor) or live_streams.role_for(p_session,p_actor) not in ('host','producer') then raise exception 'ACCESS_DENIED';end if;
 if p_width is null or p_height is null or p_width not between 1 and 4096 or p_height not between 1 and 4096 then raise exception 'INVALID_IMAGE';end if;
 select * into asset from live_streams.cover_uploads where object_path=p_path and session_id=p_session and user_id=p_actor for update;
 if not found or asset.created_at<now()-interval '2 hours' and asset.finalized_at is null then raise exception 'UPLOAD_NOT_AVAILABLE';end if;
 select o.metadata into metadata from storage.objects o where o.bucket_id='live-covers' and o.name=p_path;
 if metadata is null or metadata->>'mimetype' is distinct from 'image/jpeg' or coalesce(metadata->>'size','') !~ '^[0-9]{1,7}$' then raise exception 'INVALID_IMAGE';end if;
 if (metadata->>'size')::integer not between 4 and 2097152 then raise exception 'INVALID_IMAGE';end if;
 update live_streams.cover_uploads set finalized_at=coalesce(finalized_at,now()) where object_path=p_path;
 update live_streams.sessions set cover_object_path=p_path,thumbnail_url=null,updated_at=now() where id=p_session;
 return jsonb_build_object('ok',true,'session_id',p_session,'object_path',p_path);
end $$;
create function live_streams.cover_paths(p_sessions uuid[]) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();admin boolean:=false;items jsonb;
begin
 if p_sessions is null or cardinality(p_sessions)>24 then raise exception 'INVALID_COVER_BATCH';end if;
 if live_streams.staff_role(uid) is not null then perform live_streams.require_admin(false);admin:=true;else uid:=live_streams.require_user();end if;
 select coalesce(jsonb_agg(jsonb_build_object('session_id',s.id,'object_path',s.cover_object_path)),'[]') into items
 from live_streams.sessions s where s.id=any(p_sessions) and s.cover_object_path is not null and (admin or live_streams.can_view(s.id,uid));
 return jsonb_build_object('items',items);
end $$;
create function live_streams.can_read_cover(p_path text) returns boolean language plpgsql stable security definer set search_path='' as $$
declare uid uuid;
begin
 begin uid:=live_streams.require_user();exception when others then return false;end;
 return exists(select 1 from live_streams.sessions s where s.cover_object_path=p_path and live_streams.can_view(s.id,uid));
end $$;
do $$begin
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('live-covers','live-covers',false,2097152,array['image/jpeg']) on conflict(id) do nothing;
  if exists(select 1 from storage.buckets where id='live-covers' and public) then raise exception 'PRIVATE_LIVE_COVER_BUCKET_REQUIRED';end if;
  execute $policy$create policy live_cover_read on storage.objects for select to authenticated using(bucket_id='live-covers' and live_streams.can_read_cover(name))$policy$;
  execute $policy$create policy live_cover_read_guard on storage.objects as restrictive for select to authenticated using(bucket_id<>'live-covers' or live_streams.can_read_cover(name))$policy$;
  execute $policy$create policy live_cover_server_insert on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'live-covers')$policy$;
  execute $policy$create policy live_cover_immutable_update on storage.objects as restrictive for update to authenticated using(bucket_id<>'live-covers') with check(bucket_id<>'live-covers')$policy$;
  execute $policy$create policy live_cover_server_delete on storage.objects as restrictive for delete to authenticated using(bucket_id<>'live-covers')$policy$;
 end if;
end $$;
create function live_streams.relationship_revoked() returns trigger language plpgsql security definer set search_path='' as $$
declare sid uuid;host_a uuid;host_b uuid;
begin
 if tg_table_name='blocked_users' then host_a:=new.blocker_id;host_b:=new.blocked_id;
 else host_a:=old.following_id;host_b:=null;end if;
 for sid in select id from live_streams.sessions where host_id in (host_a,host_b) and state in ('scheduled','backstage','starting','live','reconnecting')
  and (tg_table_name='blocked_users' or audience='followers') loop
  update live_streams.sessions set chat_epoch=gen_random_uuid() where id=sid;
  perform live_streams.broadcast(sid,'access_changed',jsonb_build_object('session_id',sid));
 end loop;
 return null;
end $$;
create trigger live_block_revocation after insert on public.blocked_users for each row execute function live_streams.relationship_revoked();
create trigger live_follow_revocation after delete on public.follows for each row execute function live_streams.relationship_revoked();
do $$ begin
 if to_regclass('realtime.messages') is not null then
  execute $policy$create policy live_broadcast_read on realtime.messages for select to authenticated using(extension='broadcast' and live_streams.can_receive((select realtime.topic())))$policy$;
  execute $policy$create policy live_broadcast_read_guard on realtime.messages as restrictive for select to authenticated using(
   ((select realtime.topic()) not like 'live:%' and (select realtime.topic()) not like 'live-control:%') or (extension='broadcast' and live_streams.can_receive((select realtime.topic()))))$policy$;
  execute $policy$create policy live_broadcast_server_only on realtime.messages as restrictive for insert to authenticated with check(
   (select realtime.topic()) not like 'live:%' and (select realtime.topic()) not like 'live-control:%')$policy$;
 end if;
end $$;

-- Public functions are invoker wrappers. Privileged implementations are in an
-- unexposed schema, authenticate internally, and receive explicit grants only.
create function public.live_directory(p_filter text default 'for_you',p_topic text default null,p_state text default 'live',p_cursor jsonb default null,p_limit integer default 24) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.directory(p_filter,p_topic,p_state,p_cursor,p_limit); $$;
create function public.live_session(p_session_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.detail(p_session_id,false); $$;
create function public.live_messages(p_session_id uuid,p_before jsonb default null,p_limit integer default 50) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.messages_page(p_session_id,p_before,p_limit); $$;
create function public.live_command(p_action text,p_session_id uuid,p_payload jsonb,p_request_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.command(p_action,p_session_id,p_payload,p_request_id); $$;
create function public.live_admin_directory(p_state text default null,p_cursor jsonb default null,p_limit integer default 50) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.admin_directory(p_state,p_cursor,p_limit); $$;
create function public.live_admin_session(p_session_id uuid,p_audit_cursor jsonb default null,p_report_cursor jsonb default null) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.admin_detail(p_session_id,p_audit_cursor,p_report_cursor); $$;
create function public.live_provider_access(p_session_id uuid,p_purpose text) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.provider_access(p_session_id,p_purpose); $$;
create function public.live_prepare_control(p_session_id uuid,p_action text,p_request_id uuid,p_scene jsonb default null,p_reason text default null) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.prepare_control(p_session_id,p_action,p_request_id,p_scene,p_reason); $$;
create function public.live_service_context(p_session_id uuid,p_actor_id uuid,p_auth_session_id uuid,p_purpose text,p_operation_id uuid default null) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.service_context(p_session_id,p_actor_id,p_auth_session_id,p_purpose,p_operation_id); $$;
create function public.live_finish_control(p_operation_id uuid,p_lease_id uuid,p_accepted boolean,p_error text default null,p_published jsonb default '[]') returns jsonb language sql security invoker set search_path='' as $$ select live_streams.finish_control(p_operation_id,p_lease_id,p_accepted,p_error,p_published); $$;
create function public.live_provider_event(p_id text,p_instance uuid,p_type text,p_time timestamptz,p_digest text) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.provider_event(p_id,p_instance,p_type,p_time,p_digest); $$;
create function public.live_maintenance(p_limit integer default 1000) returns jsonb language plpgsql security invoker set search_path='' as $$ begin if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED';end if;return live_streams.maintenance(p_limit);end $$;
create function public.live_claim_outbox(p_limit integer default 10) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.claim_outbox(p_limit); $$;
create function public.live_finish_outbox(p_id uuid,p_lease uuid,p_ok boolean,p_error text default null) returns jsonb language sql security invoker set search_path='' as $$ select live_streams.finish_outbox(p_id,p_lease,p_ok,p_error); $$;
create function public.live_cover_upload(p_session_id uuid,p_action text,p_object_path text default null,p_request_id uuid default null) returns jsonb language sql security invoker set search_path='' as $$select live_streams.cover_upload(p_session_id,p_action,p_object_path,p_request_id);$$;
create function public.live_cover_paths(p_session_ids uuid[]) returns jsonb language sql security invoker set search_path='' as $$select live_streams.cover_paths(p_session_ids);$$;
