revoke all on all functions in schema live_streams from public,anon,authenticated,service_role;
do $$ declare r record;begin
 for r in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'live\_%' escape '\' loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',r.signature);
 end loop;
end $$;
grant execute on function live_streams.directory(text,text,text,jsonb,integer),live_streams.detail(uuid,boolean),live_streams.messages_page(uuid,jsonb,integer),
 live_streams.command(text,uuid,jsonb,uuid),live_streams.admin_directory(text,jsonb,integer),live_streams.admin_detail(uuid,jsonb,jsonb),
 live_streams.provider_access(uuid,text),live_streams.prepare_control(uuid,text,uuid,jsonb,text),live_streams.can_receive(text) to authenticated;
grant execute on function public.live_directory(text,text,text,jsonb,integer),public.live_session(uuid),public.live_messages(uuid,jsonb,integer),
 public.live_command(text,uuid,jsonb,uuid),public.live_admin_directory(text,jsonb,integer),public.live_admin_session(uuid,jsonb,jsonb),
 public.live_provider_access(uuid,text),public.live_prepare_control(uuid,text,uuid,jsonb,text) to authenticated;
grant execute on function live_streams.service_context(uuid,uuid,uuid,text,uuid),live_streams.finish_control(uuid,uuid,boolean,text,jsonb),
 live_streams.provider_event(text,uuid,text,timestamptz,text),live_streams.maintenance(integer),live_streams.claim_outbox(integer),live_streams.finish_outbox(uuid,uuid,boolean,text) to service_role;
grant execute on function public.live_service_context(uuid,uuid,uuid,text,uuid),public.live_finish_control(uuid,uuid,boolean,text,jsonb),
 public.live_provider_event(text,uuid,text,timestamptz,text),public.live_maintenance(integer),public.live_claim_outbox(integer),public.live_finish_outbox(uuid,uuid,boolean,text) to service_role;
grant execute on function public.live_cover_upload(uuid,text,text,uuid),public.live_cover_paths(uuid[]),live_streams.cover_upload(uuid,text,text,uuid),live_streams.cover_paths(uuid[]),live_streams.can_read_cover(text) to authenticated;
grant execute on function public.live_cover_finalize(uuid,uuid,uuid,text,integer,integer),live_streams.cover_finalize(uuid,uuid,uuid,text,integer,integer) to service_role;

-- Local DB maintenance is separate from the provider outbox worker. It emits
-- notifications only after an operator enables reminders, and bounds each run.
do $$ begin
 if to_regprocedure('cron.schedule(text,text,text)') is not null then
  perform cron.schedule('platinum-live-maintenance','* * * * *','select live_streams.maintenance(1000);');
 end if;
end $$;
notify pgrst,'reload schema';

$live_core$;
 elsif to_regclass('live_streams.settings') is null
  or to_regprocedure('live_streams.service_context(uuid,uuid,uuid,text,uuid)') is null then
  raise exception 'LIVE_EXISTING_SCHEMA_NOT_RECOGNIZED';
 end if;
end $install$;
-- Live-owned compatibility boundary. Existing account/security systems are
-- consulted when installed; this never creates substitutes for those systems.
create or replace function live_streams.account_available(p_user uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare permitted boolean;
begin
 select exists(select 1 from auth.users u join public.profiles p on p.id=u.id
  where u.id=p_user and u.deleted_at is null and not coalesce(u.is_anonymous,false)
  and (u.banned_until is null or u.banned_until<=now()) and p.deactivated_at is null
  and (p.restricted_until is null or p.restricted_until<=now())) into permitted;
 if not permitted then return false;end if;
 if to_regclass('admin_ops.staff_social_shells') is not null then
  execute 'select not exists(select 1 from admin_ops.staff_social_shells where user_id=$1)' into permitted using p_user;
  if not permitted then return false;end if;
 end if;
 if to_regclass('account_erasure.jobs') is not null then
  execute 'select not exists(select 1 from account_erasure.jobs where user_id=$1 and state<>''completed'')' into permitted using p_user;
  if not permitted then return false;end if;
 end if;
 return true;
end $$;
create or replace function live_streams.business_actor(p_user uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare business boolean;
begin
 select exists(select 1 from public.profiles where id=p_user and account_type='business') into business;
 if not business and to_regclass('business_auth.accounts') is not null then
  execute 'select exists(select 1 from business_auth.accounts where business_id=$1)' into business using p_user;
 end if;
 return business;
end $$;
create or replace function live_streams.business_session_valid(p_user uuid,p_session uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare permitted boolean;
begin
 if not live_streams.business_actor(p_user) then return true;end if;
 if to_regnamespace('business_auth') is not null then
  -- An installed but incomplete stronger guard is an error, never a fallback.
  execute 'select business_auth.session_allowed($1,$2)' into permitted using p_user,p_session;
  return coalesce(permitted,false);
 end if;
 -- The deployed production Studio binds access members to Auth sessions.
 -- Live requires that binding even when the legacy Studio has an owner default.
 return exists(select 1 from public.studio_session_members sm
  join public.business_access_members m on m.id=sm.member_id and m.business_id=sm.business_id
  where sm.session_id=p_session::text and sm.business_id=p_user and m.active);
end $$;
create or replace function live_streams.active_user(p_user uuid,p_session uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select live_streams.account_available(p_user) and live_streams.business_session_valid(p_user,p_session)
  and exists(select 1 from auth.sessions where id=p_session and user_id=p_user
    and (not_after is null or not_after>now()));
$$;
create or replace function live_streams.publisher_allowed(p_user uuid,p_session uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select live_streams.active_user(p_user,p_session) and (not live_streams.business_actor(p_user)
  or exists(select 1 from public.studio_session_members sm
   join public.business_access_members m on m.id=sm.member_id and m.business_id=sm.business_id
   where sm.session_id=p_session::text and sm.business_id=p_user and m.active and m.role in ('owner','admin','editor')));
$$;
create or replace function live_streams.require_user() returns uuid
language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();sid uuid;permitted boolean;
begin
 begin sid:=(auth.jwt()->>'session_id')::uuid;exception when others then raise exception 'AUTH_REQUIRED' using errcode='42501';end;
 if uid is null or sid is null or not live_streams.active_user(uid,sid) then
  raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 if to_regprocedure('public.business_session_allowed()') is not null then
  execute 'select public.business_session_allowed()' into permitted;
  if not coalesce(permitted,false) then raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 end if;
 return uid;
end $$;
revoke all on function live_streams.account_available(uuid),live_streams.business_actor(uuid),
 live_streams.business_session_valid(uuid,uuid),live_streams.active_user(uuid,uuid),
 live_streams.publisher_allowed(uuid,uuid),live_streams.require_user()
 from public,anon,authenticated,service_role;

create or replace function live_streams.can_view(p_session uuid,p_user uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from live_streams.sessions s join public.profiles p on p.id=s.host_id join auth.users u on u.id=s.host_id
 where s.id=p_session and p_user is not null and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now())
 and (p.restricted_until is null or p.restricted_until<=now())
 and live_streams.account_available(s.host_id)
 and not exists(select 1 from live_streams.exclusions x where x.session_id=s.id and x.user_id=p_user)
 and not exists(select 1 from public.blocked_users b where (b.blocker_id=p_user and b.blocked_id=s.host_id) or (b.blocker_id=s.host_id and b.blocked_id=p_user))
 and (s.host_id=p_user or exists(select 1 from live_streams.members m where m.session_id=s.id and m.user_id=p_user and m.status in ('invited','accepted'))
  or (s.state in ('scheduled','starting','live','reconnecting','ending','ended') and (s.audience='public'
   or (s.audience='followers' and exists(select 1 from public.follows f where f.follower_id=p_user and f.following_id=s.host_id))))));
$$;
create or replace function live_streams.service_context(p_session uuid,p_actor uuid,p_auth_session uuid,p_purpose text,p_operation uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s live_streams.sessions;ps live_streams.provider_sessions;c live_streams.controls;cfg live_streams.settings;role text;member_id uuid;allowed jsonb;lease uuid;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED' using errcode='42501';end if;
 if not live_streams.active_user(p_actor,p_auth_session) and not (
  p_purpose in ('playback','control','control_check') and live_streams.staff_role(p_actor) is not null
  and public.triniti_admin_session_check(p_actor,p_auth_session)
  and exists(select 1 from auth.users u join auth.sessions a on a.user_id=u.id where u.id=p_actor and a.id=p_auth_session and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) and (a.not_after is null or a.not_after>now()))
 ) then raise exception 'AUTH_REQUIRED';end if;
 select * into s from live_streams.sessions where id=p_session;
 select * into ps from live_streams.provider_sessions where session_id=p_session;
 select * into cfg from live_streams.settings where singleton;
 if s.id is null or ps.session_id is null then raise exception 'LIVE_NOT_AVAILABLE';end if;
 role:=live_streams.role_for(p_session,p_actor);
 if not live_streams.can_view(p_session,p_actor) and not (p_purpose in ('playback','control','control_check') and live_streams.staff_role(p_actor) in ('super_admin','platform_admin','trust_safety','ops_engineer','analyst','auditor_readonly','finance_admin') and public.triniti_admin_session_check(p_actor,p_auth_session)) then raise exception 'ACCESS_DENIED';end if;
 if p_purpose='stage' then
  if not live_streams.publisher_allowed(p_actor,p_auth_session) then raise exception 'ACCESS_DENIED';end if;
  if not cfg.stage_enabled or role not in ('host','producer','camera','guest') or s.state not in ('backstage','scheduled','starting','live','reconnecting') then raise exception 'ACCESS_DENIED';end if;
  if role='host' then member_id:=p_actor;else select provider_identity into member_id from live_streams.members where session_id=p_session and user_id=p_actor and status='accepted';end if;
  if member_id is null then raise exception 'ACCESS_DENIED';end if;
  insert into live_streams.stage_grants(session_id,user_id,auth_session_id,provider_identity,expires_at)
  values(p_session,p_actor,p_auth_session,member_id,now()+interval '6 hours')
  on conflict(session_id,user_id,auth_session_id,provider_identity) do update set expires_at=excluded.expires_at,revoked_at=null;
 elsif p_purpose='playback' then
  if not cfg.delivery_enabled or (s.audience<>'public' and not cfg.private_delivery_enabled) or (s.state not in ('live','reconnecting') and not (s.state='ended' and s.replay_available)) then raise exception 'LIVE_NOT_AVAILABLE';end if;
 elsif p_purpose in ('control','control_check') then
  select * into c from live_streams.controls where id=p_operation and session_id=p_session and actor_id=p_actor and auth_session_id=p_auth_session for update;
  if not found then raise exception 'CONTROL_NOT_FOUND';end if;
  if role not in ('host','producer') and not (c.action='stop' and live_streams.staff_role(p_actor) in ('super_admin','platform_admin','trust_safety') and public.triniti_admin_session_check(p_actor,p_auth_session)) then raise exception 'ACCESS_DENIED';end if;
  if role in ('host','producer') and not live_streams.publisher_allowed(p_actor,p_auth_session) then raise exception 'ACCESS_DENIED';end if;
  if p_purpose='control_check' then
   if c.status<>'processing' or c.lease_until<=clock_timestamp() then raise exception 'CONTROL_LEASE_EXPIRED';end if;
   lease:=c.lease_id;
  else
  if c.status='accepted' then return jsonb_build_object('completed',true,'result',c.result);end if;
  if c.status='processing' and c.lease_until>clock_timestamp() then raise exception 'CONTROL_IN_PROGRESS';end if;
  if c.status='failed' then raise exception 'CONTROL_FAILED';end if;
  lease:=gen_random_uuid();
  update live_streams.controls set status='processing',lease_id=lease,lease_until=clock_timestamp()+interval '45 seconds',updated_at=now() where id=c.id;
  end if;
 else raise exception 'INVALID_PURPOSE';end if;
 select coalesce(jsonb_agg(v),'[]') into allowed from (
  select s.host_id::text as provider_identity,'host'::text as role,s.host_id as user_id
   where exists(select 1 from live_streams.stage_grants g where g.session_id=p_session and g.user_id=s.host_id and g.provider_identity=s.host_id
    and g.revoked_at is null and g.expires_at>now() and live_streams.publisher_allowed(g.user_id,g.auth_session_id))
  union all select m.provider_identity::text,m.role,m.user_id from live_streams.members m
   join public.profiles p on p.id=m.user_id join auth.users u on u.id=p.id
   where m.session_id=p_session and m.status='accepted' and m.role in ('producer','camera','guest')
    and exists(select 1 from live_streams.stage_grants g where g.session_id=p_session and g.user_id=m.user_id and g.provider_identity=m.provider_identity
     and g.revoked_at is null and g.expires_at>now() and live_streams.publisher_allowed(g.user_id,g.auth_session_id))
    and p.deactivated_at is null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now())
    and (p.restricted_until is null or p.restricted_until<=now()) and live_streams.can_view(p_session,m.user_id)
    and live_streams.account_available(m.user_id)
    and not exists(select 1 from live_streams.exclusions x where x.session_id=p_session and x.user_id=m.user_id)
 ) v;
 return jsonb_build_object('session_id',s.id,'state',s.state,'host_id',s.host_id,'audience',s.audience,'recording_enabled',s.recording_enabled,
  'room_name',ps.room_name,'instance_id',ps.instance_id,'playback_path',case when s.state='ended' then ps.replay_path else 'live/'||s.id::text||'/'||ps.instance_id::text||'/master.m3u8' end,
  'role',role,'provider_identity',member_id,'allowed_participants',allowed,'max_stage_members',cfg.max_stage_members,
  'action',c.action,'payload',c.payload,'lease_id',lease,'active_scene',ps.active_scene);
end $$;
create or replace function live_streams.detail(p_session uuid,p_admin boolean default false) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();s live_streams.sessions;members jsonb:='[]';gifts jsonb:='[]';role text;
begin
 if p_admin then perform live_streams.require_admin(false);else uid:=live_streams.require_user();if not live_streams.can_view(p_session,uid) then raise exception 'LIVE_NOT_AVAILABLE' using errcode='42501';end if;end if;
 select * into s from live_streams.sessions where id=p_session;if not found then raise exception 'LIVE_NOT_AVAILABLE';end if;
 role:=live_streams.role_for(p_session,uid);
 if p_admin or role in ('host','producer','moderator') then
  select coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'status',m.status,'profile',live_streams.profile_json(m.user_id)) order by m.created_at,m.user_id),'[]') into members
  from (select * from live_streams.members where session_id=p_session and status<>'removed' order by created_at,user_id limit 50) m;
 end if;
 -- Paid gifts are deliberately deferred; no catalog or checkout is exposed.
 return jsonb_build_object('session',live_streams.session_json(p_session),'role',role,'capabilities',live_streams.capabilities(p_session),'gifts',gifts,'members',members,
  'reminded',exists(select 1 from live_streams.reminders where session_id=p_session and user_id=uid),'pinned_message',live_streams.message_json(s.pinned_message_id),
  'invitation',(select jsonb_build_object('role',m.role,'status',m.status) from live_streams.members m where m.session_id=p_session and m.user_id=uid and m.status in ('invited','accepted')),
  'chat_topic','live:'||s.id::text||':'||s.chat_epoch::text);
end $$;
do $cover_install$ begin if to_regclass('live_streams.cover_cleanup') is null then execute $live_cover$
-- Immutable cover ownership, account erasure and bounded abandoned-file cleanup.
-- Storage bytes are deleted only through the Storage API by the worker.
set local lock_timeout='3s';
set local statement_timeout='60s';
alter table live_streams.settings drop constraint settings_max_stage_members_check;
alter table live_streams.settings add constraint settings_max_stage_members_check check(max_stage_members between 2 and 12);
alter table live_streams.cover_uploads add column issuer_auth_session_id uuid default nullif(auth.jwt()->>'session_id','')::uuid;
alter table live_streams.cover_uploads add column cleanup_started_at timestamptz;
create index live_cover_uploads_expiry on live_streams.cover_uploads(created_at,object_path) where cleanup_started_at is null;
create table live_streams.cover_cleanup (
 id uuid primary key default gen_random_uuid(), object_path text not null unique, user_id uuid not null,
 object_id uuid, object_version text, state text not null default 'pending' check(state in ('pending','leased','done','dead')),
 lease_id uuid, lease_until timestamptz, attempts integer not null default 0,
 available_at timestamptz not null default now(), created_at timestamptz not null default now(), last_error text
);
alter table live_streams.cover_cleanup enable row level security;
revoke all on live_streams.cover_cleanup from public,anon,authenticated,service_role;
create index live_cover_cleanup_due on live_streams.cover_cleanup(available_at,id) where state in ('pending','leased');

create function live_streams.bind_cover_owner() returns trigger language plpgsql security definer set search_path='' as $$
declare asset live_streams.cover_uploads;
begin
 if new.bucket_id<>'live-covers' then return new;end if;
 select * into asset from live_streams.cover_uploads where object_path=new.name for update;
 if not found or asset.finalized_at is not null or asset.cleanup_started_at is not null or asset.created_at<now()-interval '2 hours'
  or asset.issuer_auth_session_id is null or not live_streams.publisher_allowed(asset.user_id,asset.issuer_auth_session_id)
  or not live_streams.can_view(asset.session_id,asset.user_id) or live_streams.role_for(asset.session_id,asset.user_id) not in ('host','producer')
  or exists(select 1 from live_streams.cover_cleanup where object_path=new.name)
  then raise exception 'LIVE_COVER_UPLOAD_NOT_AUTHORIZED' using errcode='42501';end if;
 if new.name !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.jpg$'
  or split_part(new.name,'/',1)<>asset.user_id::text or split_part(new.name,'/',2)<>asset.session_id::text
  then raise exception 'LIVE_COVER_UPLOAD_NOT_AUTHORIZED' using errcode='42501';end if;
 if tg_op='UPDATE' and (old.id<>new.id or old.bucket_id<>new.bucket_id or old.name<>new.name) then raise exception 'LIVE_COVER_IMMUTABLE';end if;
 -- Signed service uploads do not inherit the user's JWT. The unforgeable
 -- database grant binds real ownership before existing erasure scans see it.
 if not live_streams.account_available(asset.user_id) then raise exception 'LIVE_COVER_UPLOAD_NOT_AUTHORIZED' using errcode='42501';end if;
 if to_regprocedure('account_erasure.assert_writable(uuid)') is not null then
  execute 'select account_erasure.assert_writable($1)' using asset.user_id;
 end if;
 new.owner:=asset.user_id;new.owner_id:=asset.user_id::text;
 return new;
end $$;
create trigger live_cover_owned_upload before insert or update on storage.objects for each row execute function live_streams.bind_cover_owner();

-- Preserve the existing erasure decisions; extend only the bucket allowlist.
do $$declare source text;anchor text:='''post-media'',''story-media''';begin
 if to_regprocedure('account_erasure.review_reason(uuid)') is null then return;end if;
 source:=pg_get_functiondef('account_erasure.review_reason(uuid)'::regprocedure);
 if (length(source)-length(replace(source,anchor,'')))/length(anchor)<>1 then raise exception 'LIVE_ERASURE_CONTRACT_CHANGED';end if;
 execute replace(source,anchor,'''live-covers'',''post-media'',''story-media''');
end $$;
-- Make a retired object permanently unavailable for finalization. This closes
-- a cleanup/finalize race without deleting storage metadata in SQL.
do $$declare source text;anchor text;begin
 source:=pg_get_functiondef('live_streams.cover_upload(uuid,text,text,uuid)'::regprocedure);
 anchor:='if asset.created_at<now()-interval ''2 hours'' then';
 if position(anchor in source)=0 then raise exception 'LIVE_COVER_UPLOAD_CONTRACT_CHANGED';end if;
 source:=replace(source,anchor,'if asset.cleanup_started_at is not null or asset.created_at<now()-interval ''2 hours'' then');
 source:=replace(source,'if not found or asset.created_at<now()-interval ''2 hours'' and asset.finalized_at is null then',
  'if not found or asset.cleanup_started_at is not null or asset.created_at<now()-interval ''2 hours'' and asset.finalized_at is null then');execute source;
 source:=pg_get_functiondef('live_streams.cover_finalize(uuid,uuid,uuid,text,integer,integer)'::regprocedure);
 anchor:='if not found or asset.created_at<now()-interval ''2 hours'' and asset.finalized_at is null then';
 if position(anchor in source)=0 then raise exception 'LIVE_COVER_FINALIZE_CONTRACT_CHANGED';end if;
 source:=replace(source,anchor,'if not found or asset.cleanup_started_at is not null or asset.created_at<now()-interval ''2 hours'' and asset.finalized_at is null then');
 source:=replace(source,'where o.bucket_id=''live-covers'' and o.name=p_path;',
  'where o.bucket_id=''live-covers'' and o.name=p_path and coalesce(o.owner_id,o.owner::text)=p_actor::text;');execute source;
end $$;

create function live_streams.cover_deleted() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into live_streams.cover_cleanup(object_path,user_id,object_id,object_version)
 select old.object_path,old.user_id,o.id,o.version from (select 1) x left join storage.objects o on o.bucket_id='live-covers' and o.name=old.object_path
 on conflict(object_path) do nothing;
 update live_streams.sessions set cover_object_path=null,updated_at=now() where cover_object_path=old.object_path;
 return old;
end $$;
create trigger live_cover_grant_deleted before delete on live_streams.cover_uploads for each row execute function live_streams.cover_deleted();

create function live_streams.claim_cover_cleanup(p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare asset live_streams.cover_uploads;items jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED';end if;
 for asset in select a.* from live_streams.cover_uploads a where a.cleanup_started_at is null and a.created_at<now()-interval '1 day'
  and not exists(select 1 from live_streams.sessions s where s.cover_object_path=a.object_path)
  order by a.created_at,a.object_path for update of a skip locked limit 50 loop
  update live_streams.cover_uploads set cleanup_started_at=now() where object_path=asset.object_path;
  insert into live_streams.cover_cleanup(object_path,user_id,object_id,object_version)
   select asset.object_path,asset.user_id,o.id,o.version from (select 1) x left join storage.objects o on o.bucket_id='live-covers' and o.name=asset.object_path
   on conflict(object_path) do nothing;
 end loop;
 with claimed as(select id from live_streams.cover_cleanup where state in ('pending','leased') and available_at<=now()
  and (lease_until is null or lease_until<=now()) and attempts<8 order by available_at,id for update skip locked limit greatest(1,least(coalesce(p_limit,25),25))),updated as(
  update live_streams.cover_cleanup c set state='leased',lease_id=gen_random_uuid(),lease_until=now()+interval '60 seconds',attempts=attempts+1
  from claimed where c.id=claimed.id returning c.*)
 select coalesce(jsonb_agg(to_jsonb(updated)),'[]') into items from updated;
 return jsonb_build_object('items',items);
end $$;
create function live_streams.check_cover_cleanup(p_id uuid,p_lease uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare job live_streams.cover_cleanup;obj storage.objects;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED';end if;
 select * into job from live_streams.cover_cleanup where id=p_id and lease_id=p_lease and state='leased' and lease_until>now() for update;
 if not found then raise exception 'COVER_LEASE_EXPIRED';end if;
 if exists(select 1 from live_streams.sessions where cover_object_path=job.object_path) then raise exception 'COVER_IN_USE';end if;
 select * into obj from storage.objects where bucket_id='live-covers' and name=job.object_path;
 if not found then return jsonb_build_object('absent',true,'object_path',job.object_path);end if;
 if (obj.id,obj.version) is distinct from (job.object_id,job.object_version) or coalesce(obj.owner_id,obj.owner::text) is distinct from job.user_id::text then
  raise exception 'COVER_OBJECT_CHANGED';end if;
 return jsonb_build_object('absent',false,'object_path',job.object_path);
end $$;
create function live_streams.finish_cover_cleanup(p_id uuid,p_lease uuid,p_ok boolean,p_error text) returns jsonb language plpgsql security definer set search_path='' as $$
declare job live_streams.cover_cleanup;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_REQUIRED';end if;
 select * into job from live_streams.cover_cleanup where id=p_id and lease_id=p_lease and state='leased' for update;
 if not found then raise exception 'COVER_LEASE_EXPIRED';end if;
 if p_ok and exists(select 1 from storage.objects where bucket_id='live-covers' and name=job.object_path) then raise exception 'COVER_BYTES_NOT_ERASED';end if;
 update live_streams.cover_cleanup set state=case when p_ok then 'done' when attempts>=8 then 'dead' else 'pending' end,
  available_at=now()+make_interval(secs=>least(900,5*(2^attempts)::integer)),lease_until=null,last_error=case when p_ok then null else left(p_error,200) end where id=job.id;
 if p_ok then delete from live_streams.cover_uploads where object_path=job.object_path and cleanup_started_at is not null;end if;
 -- Keep immutable tombstones for a month. Signed upload credentials expire in
 -- two hours, and removing the grant permanently prevents new writes.
 with old as(select id from live_streams.cover_cleanup where state='done' and created_at<now()-interval '30 days' order by created_at for update skip locked limit 25)
 delete from live_streams.cover_cleanup c using old where c.id=old.id;
 return jsonb_build_object('ok',true);
end $$;
create function public.live_claim_cover_cleanup(p_limit integer default 25) returns jsonb language sql security invoker set search_path='' as $$select live_streams.claim_cover_cleanup(p_limit);$$;
create function public.live_check_cover_cleanup(p_id uuid,p_lease uuid) returns jsonb language sql security invoker set search_path='' as $$select live_streams.check_cover_cleanup(p_id,p_lease);$$;
create function public.live_finish_cover_cleanup(p_id uuid,p_lease uuid,p_ok boolean,p_error text default null) returns jsonb language sql security invoker set search_path='' as $$select live_streams.finish_cover_cleanup(p_id,p_lease,p_ok,p_error);$$;
revoke all on function live_streams.bind_cover_owner(),live_streams.cover_deleted(),live_streams.claim_cover_cleanup(integer),live_streams.check_cover_cleanup(uuid,uuid),live_streams.finish_cover_cleanup(uuid,uuid,boolean,text),
 public.live_claim_cover_cleanup(integer),public.live_check_cover_cleanup(uuid,uuid),public.live_finish_cover_cleanup(uuid,uuid,boolean,text) from public,anon,authenticated,service_role;
grant execute on function live_streams.claim_cover_cleanup(integer),live_streams.check_cover_cleanup(uuid,uuid),live_streams.finish_cover_cleanup(uuid,uuid,boolean,text),
 public.live_claim_cover_cleanup(integer),public.live_check_cover_cleanup(uuid,uuid),public.live_finish_cover_cleanup(uuid,uuid,boolean,text) to service_role;

$live_cover$;end if;end $cover_install$;
create or replace function live_streams.bind_cover_owner() returns trigger language plpgsql security definer set search_path='' as $$
declare asset live_streams.cover_uploads;
begin
 if new.bucket_id<>'live-covers' then return new;end if;
 select * into asset from live_streams.cover_uploads where object_path=new.name for update;
 if not found or asset.finalized_at is not null or asset.cleanup_started_at is not null or asset.created_at<now()-interval '2 hours'
  or asset.issuer_auth_session_id is null or not live_streams.publisher_allowed(asset.user_id,asset.issuer_auth_session_id)
  or not live_streams.can_view(asset.session_id,asset.user_id) or live_streams.role_for(asset.session_id,asset.user_id) not in ('host','producer')
  or exists(select 1 from live_streams.cover_cleanup where object_path=new.name)
  then raise exception 'LIVE_COVER_UPLOAD_NOT_AUTHORIZED' using errcode='42501';end if;
 if new.name !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.jpg$'
  or split_part(new.name,'/',1)<>asset.user_id::text or split_part(new.name,'/',2)<>asset.session_id::text
  then raise exception 'LIVE_COVER_UPLOAD_NOT_AUTHORIZED' using errcode='42501';end if;
 if tg_op='UPDATE' and (old.id<>new.id or old.bucket_id<>new.bucket_id or old.name<>new.name) then raise exception 'LIVE_COVER_IMMUTABLE';end if;
 -- Signed service uploads do not inherit the user's JWT. The unforgeable
 -- database grant binds real ownership before existing erasure scans see it.
 if not live_streams.account_available(asset.user_id) then raise exception 'LIVE_COVER_UPLOAD_NOT_AUTHORIZED' using errcode='42501';end if;
 if to_regprocedure('account_erasure.assert_writable(uuid)') is not null then
  execute 'select account_erasure.assert_writable($1)' using asset.user_id;
 end if;
 new.owner:=asset.user_id;new.owner_id:=asset.user_id::text;
 return new;
end $$;
revoke all on function live_streams.bind_cover_owner() from public,anon,authenticated,service_role;
do $worker_install$ begin if to_regclass('live_streams.worker_settings') is null then execute $live_worker$
-- The scheduler advances already-authorized Live control and cover cleanup only. Its
-- transport-visible token is single-use, short-lived, and never a service key.
set local lock_timeout = '3s';
set local statement_timeout = '30s';

create table live_streams.worker_settings (
  singleton boolean primary key default true check (singleton),
  enabled boolean not null default false,
  project_origin text check (project_origin ~ '^https://[a-z0-9]{20}[.]supabase[.]co$'),
  max_parallel integer not null default 1 check (max_parallel between 1 and 1),
  last_issued_at timestamptz,
  last_completed_at timestamptz,
  last_failed_at timestamptz,
  check (not enabled or project_origin is not null)
);
insert into live_streams.worker_settings(singleton) values (true);

create table live_streams.worker_ticks (
  digest bytea primary key check (octet_length(digest) = 32),
  created_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null,
  consumed_at timestamptz,
  finished_at timestamptz,
  succeeded boolean,
  check (expires_at > created_at and expires_at <= created_at + interval '2 minutes'),
  check (finished_at is null or consumed_at is not null)
);
create index live_worker_ticks_active on live_streams.worker_ticks(expires_at)
  where finished_at is null;
create index live_worker_ticks_expiry on live_streams.worker_ticks(expires_at);
alter table live_streams.worker_settings enable row level security;
alter table live_streams.worker_ticks enable row level security;
revoke all on live_streams.worker_settings, live_streams.worker_ticks
  from public, anon, authenticated, service_role;

create function public.configure_live_worker_v1(p_origin text, p_enabled boolean, p_parallel integer default 1)
returns jsonb language plpgsql security definer set search_path = '' as $body$
begin
  if p_enabled is null or p_parallel is null or p_parallel not between 1 and 1
    or p_origin is null or p_origin !~ '^https://[a-z0-9]{20}[.]supabase[.]co$' then
    raise exception 'Invalid Live worker configuration';
  end if;
  update live_streams.worker_settings set project_origin = p_origin,
    enabled = p_enabled, max_parallel = p_parallel where singleton;
  return jsonb_build_object('enabled', p_enabled, 'max_parallel', p_parallel);
end $body$;

create function public.validate_live_worker_tick_v1(p_token text)
returns boolean language plpgsql security definer set search_path = '' as $body$
declare matched bytea;
begin
  if auth.jwt()->>'role' is distinct from 'service_role'
    or p_token is null or p_token !~ '^pc_live_[a-f0-9]{64}$'
    or not exists(select 1 from live_streams.worker_settings where singleton and enabled) then
    return false;
  end if;
  update live_streams.worker_ticks set consumed_at = clock_timestamp()
    where digest = extensions.digest(p_token, 'sha256') and consumed_at is null
      and finished_at is null and expires_at > clock_timestamp()
    returning digest into matched;
  return matched is not null;
end $body$;

create function public.finish_live_worker_tick_v1(p_token text, p_succeeded boolean)
returns boolean language plpgsql security definer set search_path = '' as $body$
declare finished timestamptz := clock_timestamp(); matched bytea;
begin
  if auth.jwt()->>'role' is distinct from 'service_role' or p_succeeded is null
    or p_token is null or p_token !~ '^pc_live_[a-f0-9]{64}$' then return false; end if;
  update live_streams.worker_ticks set finished_at = finished, succeeded = p_succeeded
    where digest = extensions.digest(p_token, 'sha256') and consumed_at is not null
      and finished_at is null and expires_at > finished returning digest into matched;
  if matched is null then return false; end if;
  update live_streams.worker_settings set
    last_completed_at = case when p_succeeded then finished else last_completed_at end,
    last_failed_at = case when not p_succeeded then finished else last_failed_at end where singleton;
  return true;
end $body$;

create function live_streams.enqueue_worker_tick()
returns bigint language plpgsql security definer set search_path = '' as $body$
declare settings live_streams.worker_settings%rowtype;
  issued timestamptz := clock_timestamp(); token text; request_id bigint; active_count integer;
begin
  select * into settings from live_streams.worker_settings where singleton for update skip locked;
  if not found or not settings.enabled or settings.project_origin is null
    or settings.last_issued_at > issued - interval '55 seconds' then return null; end if;
  select count(*) into active_count from live_streams.worker_ticks
    where finished_at is null and expires_at > issued;
  if active_count >= settings.max_parallel then return null; end if;
  -- One short-lived credential per minute bounds maintenance fanout.
  token := 'pc_live_' || encode(extensions.gen_random_bytes(32), 'hex');
  insert into live_streams.worker_ticks(digest, created_at, expires_at)
    values(extensions.digest(token, 'sha256'), issued, issued + interval '2 minutes');
  select net.http_post(url := settings.project_origin || '/functions/v1/live-maintenance',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || token),
    body := '{}'::jsonb, timeout_milliseconds := 30000) into request_id;
  update live_streams.worker_settings set last_issued_at = issued where singleton;
  delete from live_streams.worker_ticks where digest in (
    select digest from live_streams.worker_ticks where expires_at < issued - interval '1 day'
      order by expires_at for update skip locked limit 100);
  return request_id;
end $body$;

create function public.live_worker_status_v1()
returns jsonb language sql stable security definer set search_path = '' as $body$
  select jsonb_build_object('enabled', s.enabled, 'max_parallel', s.max_parallel,
    'last_issued_at', s.last_issued_at, 'last_completed_at', s.last_completed_at,
    'last_failed_at', s.last_failed_at, 'active_ticks', (
      select count(*) from live_streams.worker_ticks where finished_at is null and expires_at > now()))
  from live_streams.worker_settings s where s.singleton;
$body$;

revoke all on function live_streams.enqueue_worker_tick() from public, anon, authenticated, service_role;
revoke all on function public.configure_live_worker_v1(text,boolean,integer),
  public.validate_live_worker_tick_v1(text), public.finish_live_worker_tick_v1(text,boolean),
  public.live_worker_status_v1() from public, anon, authenticated;
grant execute on function public.configure_live_worker_v1(text,boolean,integer),
  public.validate_live_worker_tick_v1(text), public.finish_live_worker_tick_v1(text,boolean),
  public.live_worker_status_v1() to service_role;

do $body$ begin
  if exists(select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('platinum-live-worker', '* * * * *', 'select live_streams.enqueue_worker_tick()');
  end if;
end $body$;

$live_worker$;end if;end $worker_install$;
notify pgrst,'reload schema';
commit;
